export default [{"id":408,"question":"هل موسى  وبقية الأنبياء حجُّوا وطافوا بالبيت العتيق؟","title":"هل صح حج الأنبياء ودفن بعضهم بالحطيم؟","answer":"الجواب: جاءت عدة أحاديث عن موسى وعن هارون وعن هود أنهم حجّوا، أما بقية الرسل فما أعلم شيئًا في هذا يدل على العموم، لا أذكر شيئًا، وكم يخفى علينا من العلم، لكن لا أذكر شيئًا في بقية الرسل عليهم الصلاة والسلام.\nس: وبقية السؤال يقول: هل فعلًا بعض الأنبياء يُدفن في الحطيم؟\nالشيخ: هذا مما يُقال ولا دليل عليه، يُقال في بعض التاريخ، لكن لا دليل عليه، ولا يُعتمد عليه، ولو قُدّر أنهم دُفنوا فقد ذهبت آثارهم في الحطيم، ولم تبقَ لهم آثار ولا بناء عليهم ولا قبور، فحكمهم كالعدم؛ لأنه لا أثر لهم اليوم.","link":"https://binbaz.org.sa/fatwas/4823/هل-صح-حج-الانبياء-ودفن-بعضهم-بالحطيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0466.mp3","categories":["التاريخ والسيرة"]},{"id":456,"question":"الشارح يقول: وفيه دليل على أن الخندق كانت سنة أربع، والقول بأنها سنة خمس يردها هذا الحديث، وأجمعوا على أن أُحُدًا كانت سنة ثلاث؟","title":"متى كانت غزوة الخندق؟","answer":"الجواب: لا، غلط، الخندق سنة خمس، لكنه كان في أُحُد في أول الرابعة عشر، وفي الخندق قد أكمل الخامسة عشر، وصار في السادسة عشر.\n(دروس شرح بلوغ المرام، كتاب البيوع)","link":"https://binbaz.org.sa/fatwas/6180/متى-كانت-غزوة-الخندق","audio":"https://files.zadapps.info/binbaz.org.sa/7'andk.015.mp3","categories":["التاريخ والسيرة"]},{"id":575,"question":"لو لم يشفع عثمان لقَتَلَ النبي ﷺ عبد الله بن سعد بن أبي سرح؟","title":"ما صحة ودلالة قبول توبة ابن أبي السرح؟","answer":"الجواب: شفع عثمان ، وجاء تائبًا؛ فدل على أن من جاء تائبًا نادمًا قبل القدرة عليه لا بأس أن تقبل توبته.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6406/ما-صحة-ودلالة-قبول-توبة-ابن-ابي-السرح","audio":"https://files.zadapps.info/binbaz.org.sa/maram141 - 01 -  Start.mp3","categories":["التاريخ والسيرة"]},{"id":580,"question":"سبب شفاعة عثمان لعبدالله بن سعد بن أبي سرح؟","title":"ما سبب شفاعة عثمان لعبدالله بن أبي سرح؟","answer":"الجواب: لأنه أخوه من الرضاعة وجاء تائبًا نادمًا قبل القدرة عليه؛ فرأى عثمان أن هذا مناسب.\n(دروس شرح بلوغ المرام، كتاب الجنايات)","link":"https://binbaz.org.sa/fatwas/6411/ما-سبب-شفاعة-عثمان-لعبدالله-بن-ابي-سرح","audio":"https://files.zadapps.info/binbaz.org.sa/maram146 - 02 - .mp3","categories":["التاريخ والسيرة"]},{"id":893,"question":"أخ يسأل ويقول: سماحة الوالد الكريم، جزاك الله خيرًا على ما تقوم به في سبيل الدَّعوة، أفيدونا جزاكم الله خيرًا، حيث ورد في بعض، أو قرأتُ في بعض الكتب أنَّ النبي ﷺ قد دخل الكعبةَ المُشرفة أربع مرات، فهل هذا صحيح أو أنه دخل مرةً واحدةً؟","title":"هل دخل النبي ﷺ الكعبة أكثر من مرة؟","answer":"الجواب: أنا لا أذكر إلا أنه دخلها مرةً واحدةً يوم الفتح، أما قبل ذلك أو بعده فلا أذكر، ويمكن مراجعة كتب أهل الحديث؛ لأنَّ هذا شيء مُتيسر بحمد الله مُراجعته، لكن لا أذكر إلا أنه دخلها عام الفتح، وأمر بمحو الصور التي فيها، وصلَّى فيها عليه الصلاة والسلام، هكذا جاء في \"الصحيحين\" من حديث ابن عمر.","link":"https://binbaz.org.sa/fatwas/20934/هل-دخل-النبي-ﷺ-الكعبة-اكثر-من-مرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0730هل صحيح أن النبي صلى الله عليه وسلم دخل الكعبة المشرفة أربع مرات؟ ابن باز فتاوى المحاضرات.mp3","categories":["التاريخ والسيرة"]},{"id":1126,"question":"إنَّ ليلة السابع والعشرين من رجب هي ليلة الإسراء كما يقول بعضُهم، ولكن بعض إخواننا في الله أنكر ذلك، فما رأي فضيلتكم في هذا جزاكم الله خيرًا؟ وهل في هذا الوقت عملٌ مشروعٌ يعمله المرء؟","title":"هل صح شيء في ليلة الإسراء والاحتفال بها؟","answer":"الجواب:\nبعض المؤرخين للسيرة يرون أنَّ ليلة سبعٍ وعشرين هي ليلة الإسراء والمعراج، ويحتفلون بها، وهذا شيءٌ لا أصلَ له، وليلة الإسراء والمعراج لم تُحفظ، وهذا بحكمة الله  أن نسيها الناسُ، وذلك من أسباب عدم الغلو فيها. وهي حقٌّ، فالله جل وعلا أسرى بنبيه إلى المسجد الأقصى، ثم عُرج به إلى السماء، كما قال جلَّ وعلا: سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى [الإسراء:1]، هذا أمرٌ مقطوعٌ به، لا شكَّ فيه، ولكنَّ الليلة التي وقع فيها هذا الأمر غير معروفةٍ، ومَن قال: إنها ليلة سبعٍ وعشرين من رجب فقد غلط، وليس معه دليلٌ، والحديث الوارد في ذلك ضعيفٌ.\nولو عُلمت، ولو تيقَّنَّاها في ليلة سبعٍ وعشرين أو في غيرها؛ لم يُشرع لنا أن نُحييها بعبادةٍ أو باحتفالٍ؛ لأن هذا بدعة، لو كان هذا مشروعًا لفعله النبي ﷺ، واحتفل بها، أو خلفاؤه الراشدون، أو الصحابة، فلما لم يحتفلوا بها: لا في حياته ﷺ، ولا بعد وفاته، دلَّ على أن الاحتفال بها بدعة، ليس لنا أن نُحْدِث شيئًا ما شرعه الله، فالله ذمَّ قومًا فقال: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]، وقال الله سبحانه في حقِّ نبيه ﷺ: ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الْأَمْرِ فَاتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَاءَ الَّذِينَ لَا يَعْلَمُونَ  ۝  إِنَّهُمْ لَنْ يُغْنُوا عَنْكَ مِنَ اللَّهِ شَيْئًا [الجاثية:18- 19]، فالله أمره أن يلزم الشريعة فقط، وأنكر على مَن خالفها أو أحدث شيئًا ما شرعه الله.\nوقال عليه الصلاة والسلام: مَن أحدث في أمرنا –يعني: في ديننا- هذا ما ليس منه فهو ردٌّ يعني: فهو مردودٌ، وقال: خير الحديث كتاب الله، وخير الهدي هدي محمدٍ ﷺ، وشرّ الأمور مُحدثاتها، وكل بدعةٍ ضلالة.\nفلا يجوز الاحتفال بليلة سبعٍ وعشرين على أنها ليلة الإسراء والمعراج، ولا بغيرها من الليالي التي لم يشرع الله الاحتفال بها.\nأما ليالي العشر من رمضان فهذه مشروعٌ فيها قيام الليل والتَّهجد والقراءة والدعاء؛ لأن الرسول فعلها عليه الصلاة والسلام، وفيها ليلة القدر.\nفالواجب الانتباه والحذر من البدع، ولا ينبغي للعاقل أن يغترَّ بالناس، يقول: فعل الناس، لا، لا يغترَّ بفعل الناس، العبرة بالدليل، فلا يغتر بفعل الناس بالموالد، وكون كثيرٍ من الناس يفعله في كثيرٍ من البلدان الإسلامية، لا يغتر بهذا، يقول الله جلَّ وعلا: وَإِنْ تُطِعْ أَكْثَرَ مَنْ فِي الْأَرْضِ يُضِلُّوكَ عَنْ سَبِيلِ اللَّهِ [الأنعام:116].\nفالواجب التَّمسك بالدليل، ومَن فعل فعلًا يتعبد به يُقال له: ما دليلك؟ وأيش الدليل؟ لسنا نتعبد بالأهواء، لو قال إنسانٌ: أنا أزيد في الأذان، بدلًا من أن نقول: لا إله إلا الله مرة واحدة، نحطّها مرتين: لا إله إلا الله، لا إله إلا الله، في الأذان، هذا بدعة، ولو أنها كلمة حقٍّ، ولو قال: أحطّ التَّكبير خمس بدل أربع في أوله، خمس بدعة، ولو قال: أحطّ الشهادتين ست شهادات، صارت بدعة، ولو قال: حي على الصلاة، أحطها ثلاثًا، صارت بدعة، لا بد أن تُقيد بالشريعة.\nوهكذا لو قال: الظهر أحطّها خمسًا، والعصر أحطّها خمسًا، والعشاء أحطّها خمسًا، والمغرب أحطّها أربعًا، والفجر أحطّها أربعًا، صارت بدعة، منكر، باطل، الناس عليهم التَّقيد بالشريعة، ليس لهم الزيادة.\nوهكذا لو قال: خمس صلوات ما تكفي، نحطّها ست صلوات، تصير الضحى واحدة، أو وسط الليل، صارت بدعة منكرًا ما يجوز، ليس للناس الزيادة إلا ما شرعه الله أبدًا، لا يزيدون، أو قال: صيام رمضان ما يكفي، نحطّ شهرًا آخر، لازم الناس يصومون ربيع أول أو ربيع ثانٍ زيادة خيرٍ؛ ما يجوز، لا بد من التَّقيُّد بالشريعة وعدم الزيادة.","link":"https://binbaz.org.sa/fatwas/21178/هل-صح-شيء-في-ليلة-الاسراء-والاحتفال-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0974هل ليلة السابع والعشرين من رجب في ليلة الأسراء وهل في هذه الليلة عمل مشروع؟.mp3","categories":["التاريخ والسيرة","البدع والمحدثات"]},{"id":1224,"question":"مَن هو أول مَن بنى البيت؟ هل هو آدم أم إبراهيم؟","title":"هل أول من بنى البيت هو آدم أم إبراهيم؟","answer":"الجواب:\nالصواب أنه إبراهيم مثلما تقدَّم، كما نصَّ عليه الكتابُ العزيز: وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ [البقرة:127]، لم يأتِ نصٌّ يدل على أنه سبقه أحدٌ عليه الصلاة والسلام.\nولما سُئل النبيُّ ﷺ عن أول بيتٍ وُضع للناس قال: بيت الله العتيق، قيل: ثم أي؟ قال: البيت المقدس، بيت إيلياء، قال: كم بينهما؟ قال: أربعون عامًا، فأول مسجدٍ هو هذا المسجد الذي فيه الكعبة، وثاني مسجدٍ القدس -مسجد إيلياء- بينهم أربعون عامًا، بناه يعقوب حفيد إبراهيم عليه الصلاة والسلام، ثم جدَّده سليمان بن داود عليهما الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21288/هل-اول-من-بنى-البيت-هو-ادم-ام-ابراهيم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1031من هو أول من بنى البيت هل هو آدم أم إبراهيم؟ ابن باز.mp3","categories":["التاريخ والسيرة"]},{"id":1236,"question":"يعتقد البعضُ من العامَّة أنَّ لقاء آدم بحواء لأول مرةٍ كان في عرفات، وبقرب الجبل، فلذا سُميت: عرفات، ما مدى صحَّة ذلك؟","title":"ما صحة اعتقاد لقاء آدم وحواء بعرفات؟","answer":"الجواب:\nالشيخ: لا أعرف له أصلًا، لا أعرف لهذا أصلًا.","link":"https://binbaz.org.sa/fatwas/21299/ما-صحة-اعتقاد-لقاء-ادم-وحواء-بعرفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1042هل صحيح أن لقاء آدم بحواء لأول مرة كان في عرفات وبقرب الجبل ولذ سمي بهذا الأسم؟ ابن باز.mp3","categories":["التاريخ والسيرة"]},{"id":1254,"question":"لقد ظهرت كتبٌ كثيرةٌ تتكلم عن الفتنة التي حصلت بين الصَّحابة في عهدي الخليفتين الراشدين: عثمان وعلي رضي الله عن الجميع، فنرجو من سماحتكم أن تُرشدونا إلى أفضل الكتب التي تكلَّمتْ في هذا الموضوع، والتي لا يوجد بين صفحاتها أيُّ شيءٍ من الكذب والافتراء.","title":"ما أفضل الكتب حول ما شجر بين الصحابة؟","answer":"الجواب:\nنُرشدكم إلى \"العقيدة الواسطية\"، أخصر كتابٍ، كتابٌ مختصرٌ، أجاد وأفاد، وإلا فهناك  كتب مُطوَّلة، لكن \"العقيدة الواسطية\" لشيخ الإسلام ابن تيمية كتابٌ مختصرٌ مفيدٌ سليمٌ، قال فيها : \"ويمسكون –أهل السنة والجماعة- عمَّا شجر بين الصحابة، ويقولون: إنَّ هذه الآثار المروية في مساوئهم منها ما هو كذب، ومنها ما قد زِيد فيه ونُقِصَ وغُيِّر عن وجهه، والمحفوظ منه هم فيه مجتهدون: إما مجتهدون مُصيبون فلهم أجران، وإما مُخطئون فلهم أجرٌ واحدٌ، والخطأ مغفورٌ\".\nهذا الحكم في الفتنة: هم مجتهدون رضي الله عنهم وأرضاهم، لكن بعض النقل فيه شرٌّ، بعض النقل من بعض النَّقلة الضُّعفاء ينقل أشياء غير صحيحةٍ، لكن ما ثبت من أعمالهم....... مَن أصاب فله أجران، ومَن أخطأ فله أجرٌ واحدٌ.\nوأهل السنة يقولون: إنَّ عليًّا وأصحابه هم المصيبون، وأن معاوية قد أخطأ، وأن عمل معاوية عمل بغيٍ، ولكنه مجتهد؛ للمُطالبة بدم قتلة عثمان، فاجتهد فأخطأ فله أجر الاجتهاد، وسمَّاه النبيُّ: باغيًا، قال في عمار: تقتل عمّارًا الفئةُ الباغيةُ، وهم معاوية وأصحابه، قتلوه، فعليٌّ وأصحابه هم أهل العدل، ولهم البيعة الصحيحة، والذين مع معاوية بيعتهم غير صحيحةٍ، مجتهدون لهم أجرٌ واحدٌ  وأرضاهم، والواجب الكفُّ عن مساوئهم، والتَّرضي عنهم، والإيمان بأنهم مجتهدون: مَن أصاب فله أجران، ومَن أخطأ فله أجرٌ.","link":"https://binbaz.org.sa/fatwas/21321/ما-افضل-الكتب-حول-ما-شجر-بين-الصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1064ما هي أفضل الكتب التي تتكلم عن الفتنة التي حصلت بين الصحابة رضي الله عنهم.mp3","categories":["التاريخ والسيرة"]},{"id":1312,"question":"هل تُحدثنا عمَّا حصل في غزوة الخندق؟ وهل هي مُشابهة لما نحن فيه الآن؟","title":"ما العِبَر المستفادة من غزوة الخندق؟","answer":"الجواب:\nتكلَّمنا عنها قبل الأذان، غزوة الخندق جرت فيها محنةٌ عظيمةٌ، اجتمع فيها الكفار وغَزَوا المدينة، وتُسمَّى: غزوة الأحزاب، النبي ﷺ حفر خندقًا حول المدينة، وأشار إليه بهذا سلمان الفارسي، وصار هذا الخندق بينه وبين الأعداء، ومكثوا حوله شهرًا وهم مُحاصِرون للمدينة، وأنزل الله في هذا قوله تعالى: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَاءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَمْ تَرَوْهَا وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا  ۝  إِذْ جَاءُوكُمْ مِنْ فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنْكُمْ وَإِذْ زَاغَتِ الْأَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا  ۝  هُنَالِكَ ابْتُلِيَ الْمُؤْمِنُونَ وَزُلْزِلُوا زِلْزَالًا شَدِيدًا  ۝  وَإِذْ يَقُولُ الْمُنَافِقُونَ وَالَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ مَا وَعَدَنَا اللَّهُ وَرَسُولُهُ إِلَّا غُرُورًا [الأحزاب:9- 12]، هكذا نَجَم النفاق، وظهر النفاق -نعوذ بالله- فالمشركون تجمَّعوا.\nويُقال لها: غزوة الأحزاب؛ لأنَّ قريشًا جمعت أحزابًا كثيرةً: غطفان وغير غطفان، والأحابيش وغيرهم، جمعوا حتى قال أصحابُ السِّيَر: إنهم نحو عشرة آلاف، كلهم قصدوا المدينة للقضاء على النبي ﷺ بزعمهم وأصحابه، ولكنَّ الله خيَّبهم وردَّهم خائبين، والحمد لله، وأنزل الله عليهم جنودًا لم يروها من الملائكة، وأنزل عليهم ريحًا، ملائكة وريحًا، الله أهلكهم جلَّ وعلا وردَّهم خائبين سبحانه وتعالى.\nوقد بلغت الشدَّةُ مع المسلمين، ونَجَم النِّفاق، وقال المنافقون: مَا وَعَدَنَا اللَّهُ وَرَسُولُهُ إِلَّا غُرُورًا [الأحزاب:12] يعني: ما وعدنا الله من النصر إلا غرورًا، هذا ظنُّ الكافرين والمنافقين -نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21357/ما-العبر-المستفادة-من-غزوة-الخندق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1100كلام الشيخ ابن باز في غزوة الخندق.mp3","categories":["التاريخ والسيرة"]},{"id":1433,"question":"مَن يُسَمِّي \"عمر بن عبدالعزيز\" خامس الخلفاء الراشدين، مع أن معاوية.....؟","title":"حكم وصف \"خليفة راشد\" لعمر بن عبدالعزيز","answer":"الجواب:\nيُسميه بعضهم، وهو إن شاء الله خليفة راشد، لكن الخلفاء الراشدون هم الأربعة، لكن هو خليفة راشد، وكل إمام عدل يُسَمَّى خليفة راشد، كل إمام صالح يُسَمَّى خليفة راشد.\nس: العلماء متفقون على أن معاوية أحسن منه؟\nج: معاوية صحابي، معاوية أفضل منه، من الصحابة .","link":"https://binbaz.org.sa/fatwas/21528/حكم-وصف-خليفة-راشد-لعمر-بن-عبدالعزيز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل عمر بن عبدالعزيز خامس الخلفاء الراشدين.mp3","categories":["التاريخ والسيرة"]},{"id":1522,"question":"ذكرتم أمس أن ثلاثةً تكلَّموا وهم صبية: عيسى ابن مريم، والغلام صاحب جريج، وصاحب المرأة، وفي حديثٍ هنا عند الإمام أحمد، قال: حدثنا أحمد، حدثنا عفان، حدثنا حماد بن سلمة، عن ثابتٍ، عن عبدالرحمن بن أبي ليلى، عن صهيب: أنَّ رسول الله ﷺ قال: كان فيمَن كان قبلكم ملك، وكان له ساحرٌ، فلما كبر الساحر قال للملك: إني قد كبر سني، وحضرني الأجل .. وذكر قصة الغلام مع الأخدود، وفي آخرها قال: فجاءت امرأةٌ بابنٍ لها تُرضعه، فكأنَّها تقاعست أن تقع في النار، فقال الصبيُّ: اصبري يا أُمَّاه فإنَّك على الحقِّ. وذكره ابن كثير في تفسير سورة البروج؟","title":"ما عدد الذين تكلموا وهم صبية؟","answer":"الجواب:\nإذا صحَّ يكون صبيًّا رابعًا، إذا صحَّ أنه رضيع، فقد لا يكون رضيعًا، فبعض الرّضعان يتكلم، لكن إذا صحَّ أنَّه رضيع يكون رابعًا مع الثلاثة الذين ذكرهم النبيُّ ﷺ.","link":"https://binbaz.org.sa/fatwas/21621/ما-عدد-الذين-تكلموا-وهم-صبية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الذين تلكموا وهم صبية.mp3","categories":["التاريخ والسيرة"]},{"id":1625,"question":"ما الحكمة في كون الرسول ﷺ خصَّ فاطمة دون سائر أخواتها؟","title":"ما الحكمة فيما خَصَّ به النبي ﷺ فاطمة؟","answer":"الجواب:\nلأنَّ أخواتها ماتوا وما بقي إلا فاطمة.\nس: هي كانت أصغرهم؟\nج: نعم، يحتمل أنه قاله لأجل صغرها، أو لأنَّها حاضرة، أو لأسبابٍ أخرى.","link":"https://binbaz.org.sa/fatwas/21730/ما-الحكمة-فيما-خص-به-النبي-ﷺ-فاطمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكمة في كون الرسول عليه الصلاة والسلام خصَّ فاطمة دون سائر أخواتها.mp3","categories":["التاريخ والسيرة"]},{"id":2130,"question":"لماذا سُمُّوا بأصحاب الصُّفة؟","title":"معنى \"أهل الصفة\" وهل له صلة بالتصوف؟","answer":"الجواب:\nلأنَّ النبي ﷺ أنزلهم فيها، فالصُّفة معناها: الحجرة في المسجد.\nس: بعض المُتصوفة في بعض البلدان يتَّخذون من هذا الحديث كلمة \"أهل الصُّفَّة\"، فيقولون: نحن الصُّوفية، وهي مأخوذة من \"أهل الصُّفَّة\"؟\nج: لا، هذا خطأ، الصُّفَّة: الحجرة، يعني: حجرة في المسجد ينزلها الفقراء.\nس: يقولون: نحن أخذناها من هذا الحديث؟\nج: لا، هذا جهل منهم، فإنَّهم كانوا يسكنون الصُّفَّة لأجل حاجتهم إليها، فينزلونها حتى يعرفهم الناس، فيأتي مَن يأتي بصدقته أو مساعدته لهم؛ لأنَّهم يعرفون أنهم في الصُّفَّة، فيُساعدونهم بما تيسَّر.","link":"https://binbaz.org.sa/fatwas/22248/معنى-اهل-الصفة-وهل-له-صلة-بالتصوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تسمية أصحاب الصفة بهذا الاسم وهل هو دليل على التصوف.mp3","categories":["التاريخ والسيرة"]},{"id":2145,"question":"أبو سفيان ابن الحارث بن عبدالمطلب أخو النبي ﷺ من الرّضاعة، هو صخر بن حرب أو غيره؟","title":"ما قرابة أبي سفيان بن الحارث بالنبي ﷺ؟","answer":"الجواب:\nأبو سفيان ابن الحارث غير صخر بن حرب، صخر بن حرب هذا والد أم حبيبة زوجة النبي ﷺ، وهو الذي كان يقود الكفار يوم أحد ويوم الأحزاب، ثم أسلم وهداه الله والحمد لله، وأبو سفيان ابن الحارث ابن عم النبي ﷺ، فالحارث بن عبدالمطلب أخو عبدالله بن عبدالمطلب، وكان كافرًا ثم أسلم عام الفتح وحَسُن إسلامه.","link":"https://binbaz.org.sa/fatwas/22264/ما-قرابة-ابي-سفيان-بن-الحارث-بالنبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قرابة أبو سفيان ابن الحارث بن عبدالمطلب بالنبي عليه الصلاة والسلام.mp3","categories":["التاريخ والسيرة"]},{"id":2260,"question":"إلقاء المُحاضرات والنَّدوات في سيرة النبي ﷺ في يوم مولده أو الإسراء والمعراج يُعتبر من المُحدثات؟","title":"حكم المُحاضرات في السيرة يوم مولده ﷺ","answer":"الجواب:\nلا، إذا كان عن علمٍ وبصيرةٍ لا بأس.\nس: يتوافق مع اليوم الذي وُلِدَ فيه؟\nج: لا بأس، إذا سجَّل أخبار الإسراء والمعراج للفائدة فلا شيء في ذلك، إذا كان من أهل العلم ولا يضع الخُرافات.","link":"https://binbaz.org.sa/fatwas/22383/حكم-المحاضرات-في-السيرة-يوم-مولده-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إلقاء المُحاضرات والنَّدوات في سيرة النبي في يوم مولده ونحوه.mp3","categories":["التاريخ والسيرة"]},{"id":2293,"question":"هل كانت للرسول ﷺ بطانةٌ تأمره بالسُّوء؟","title":"هل كانت للرسولﷺ بطانةٌ تأمره بالسُّوء؟","answer":"الجواب:\nظاهر الحديث العموم، وأنه يُبتلى الأنبياء وغيرهم، لكن الله يعصمهم ويكفيهم: وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ [المائدة:67]، فقد يُبتلون ويكفيهم الله.","link":"https://binbaz.org.sa/fatwas/22416/هل-كانت-للرسولﷺ-بطانة-تامره-بالسوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل كانت للرسول بطانةٌ تأمره بالسُّوء.mp3","categories":["التاريخ والسيرة"]},{"id":2297,"question":"إنَّ الملائكة لتستحي من عثمان ؟","title":"معنى حياء الملائكة مِن عثمان رضي الله عنه","answer":"الجواب:\nعثمان من أرباب الحياء ، وفي حديث عمران: الحياء خيرٌ كله، لا يأتي الحياءُ إلا بخيرٍ.","link":"https://binbaz.org.sa/fatwas/22421/معنى-حياء-الملاىكة-من-عثمان-رضي-الله-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استحياء الملائكة من عثمان رضي الله عنه.mp3","categories":["التاريخ والسيرة","الآداب والأخلاق المحمودة"]},{"id":2411,"question":"امتناع الرسول ﷺ من دخول الكعبة عندما كانت الصور معلقة؟","title":"ماذا فعل النبي ﷺ للصور في الكعبة؟","answer":"الجواب:\nلا، دخل فيها وصلى فيها ومحا الصور، بعد ذلك دخل ومحاها من الجدران عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/22538/ماذا-فعل-النبي-ﷺ-للصور-في-الكعبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل امتنع الرسول من دخول الكعبة عندما كانت الصور معلقة.mp3","categories":["التاريخ والسيرة"]},{"id":2580,"question":"ماذا كانت أحكام أمهات المؤمنين وقت الصحابة؟","title":"أحكام أمهات المؤمنين في وقت الصحابة","answer":"الجواب: لا يتزوجن، الله حَرَّم عليهن أن يتزوجن بعده، ولهن الفضل والرضا والمغفرة، يُترضى عنهن، ولهن الفضل العظيم، لكن ليس لهن الزواج بغيره عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/22713/احكام-امهات-المومنين-في-وقت-الصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أحكام أمهات المؤمنين.mp3","categories":["التاريخ والسيرة"]},{"id":2583,"question":"المحرمية لأمهات المؤمنين على الصحابة؟","title":"معنى وحكم حُرْمة أمهات المؤمنين","answer":"حُرْمة حُرْمة، ما هي بمحرمية، أجنبيات، حرام عليهم وليسوا بمحارم لهن، إنما هي حُرْمة من جهة الفضل... الحق... وأمهات المؤمنين من جهة الفضل والاحترام، لا من جهة الحُرْمة.\nس: الخلوة كسائر النساء؟\nالشيخ: لا يخلو، لكن الصحابة يدخلون الاثنان والثلاثة يسألونها، على عائشة وعلى غيرها، مثل ما يدخل الإنسان الآن مع أخيه.","link":"https://binbaz.org.sa/fatwas/22716/معنى-وحكم-حرمة-امهات-المومنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حرمة أمهات المؤمنين على الصحابة.mp3","categories":["التاريخ والسيرة"]},{"id":2592,"question":"ما كذبات إبراهيم عليه الصلاة والسلام الثلاث؟","title":"ما الكذبات الثلاث التي ذكرها إبراهيم ﷺ؟","answer":"الجواب: قوله في الأصنام بل فعله كبيرهم هذا لما كسرها، قالوا من فعل هذا قال: كبيرهم؛ لعلهم يعتبرون، لعلهم ينتبهون، كبيرهم جماد ما عنده خبر، ولهذا انتبهوا وأعدوا له النار فأنجاه الله من شرهم. والثانية: قوله إني سقيم، لما تخلف إلى أصنامهم مروا عليه... قال: إني سقيم، يُوهِم أنه مريض، وهو ليس بمريض ولكنه أسقمه كفرهم وشرهم. والثالثة: أنه ذهب ومعه زوجته سارة إلى مصر فذُكِرت للملك فجيء بها إليه، وسأل إبراهيم عنها، فقال: إنها أختي، ما قال إنها زوجتي، خاف أن يغار ويأخذها، وقال: إنها أختي، فمدّ يده إليها فأصابه الله بشلل في يده، لم يستطع أن يمدّ يده إليها، فقال: ادع الله لي ولا أضرك، فدعت الله له، ثم مدّ يده فأُخذ أيضًا، فدعت له وأطلق، ثم قال: اذهبوا بها عني فما أتيتموني بإنسانة وإنما أتيتموني بشيطانة، ورد الله كيده وسلمت من شره، سارة رضي الله عنها ورحمها زوجة الخليل.\nس: هذه الثلاث تسمى كذبات؟ أليست من معاريض الكلام؟\nالشيخ: مِن ورعه عليه الصلاة والسلام سماها كذبًا، وهو أراد بذلك التعريض، لكن سماها كذبًا بالنسبة إلى ما يظهر للناس يعتبرونها كذبًا، وهو أراد بذلك أن يلفت أنظارهم إلى أن الأصنام ما عندها حَلٌّ ولا عقد، بل فعله كبيرهم، ما يفعل شيء، وفي سقيم يعذرونه لأنه مريض على ما يعرفون في عرفهم، وهو سقيم من أعمالهم الخبيثة.","link":"https://binbaz.org.sa/fatwas/22725/ما-الكذبات-الثلاث-التي-ذكرها-ابراهيم-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كذبات إبراهيم عليه الصلاة والسلام.mp3","categories":["التاريخ والسيرة"]},{"id":2643,"question":"هل اشترط النبي ﷺ على عليٍّ عدم الزواج على ابنته فاطمة؟","title":"هل اشترط النبيﷺعدم الزواج على ابنته؟","answer":"الجواب: لما أراد أن يتزوج أنكر ذلك عليه، قال ﷺ: إنه يؤذيني ما يؤذيها، وهذا خاص بفاطمة.","link":"https://binbaz.org.sa/fatwas/22778/هل-اشترط-النبيﷺعدم-الزواج-على-ابنته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل اشترط النبي على علي عدم الزواج على ابنته فاطمة.mp3","categories":["شروح الحديث","التاريخ والسيرة"]},{"id":2675,"question":"بعض شراح الحديث قالوا بأن الاحتلام لا يقع من الأنبياء؟","title":"هل يقع الاحتلام من الأنبياء؟","answer":"الجواب: لا، ما عليه دليل، ما الذي يمنع؟ ولهذا قال: \"مِنْ غير حُلْم\"، لو أنه يُمْكِن الحلم ما قال بغير حلم، الحلم قد يتراءى الإنسان في النوم أشياء فيفعل ما يفعله الإنسان مع أهله.","link":"https://binbaz.org.sa/fatwas/22813/هل-يقع-الاحتلام-من-الانبياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقع الاحتلام من الأنبياء.mp3","categories":["التاريخ والسيرة"]},{"id":2685,"question":"ابن عمرو  ألم يتعبه صوم داوود؟","title":"هل صح أن صوم داوود أتعب ابن عمرو؟","answer":"الجواب: عبدالله بن عمرو كان في آخر حياته يشق عليه، وكان يفطر أيامًا ستة ويصوم أيامًا ستة، ويقول: ما أحب أن أخل بشيء فارقت عليه النبي عليه الصلاة والسلام، فإذا عجز سرد الفطر ثم يسرد الصوم، وهذا من اجتهاده  وإلا لو ترك الحمد لله، الأمر واسع.\nس: ما ثبت عنه أنه قال ليتني أطعت وصية رسول الله ﷺ؟\nالشيخ: يمكن: ليتني قبلت رخصة رسول الله. أظنه جاء عنه اجتهادًا منه، ما أحَبَّ أن يخل بشيء فارق عليه النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/22824/هل-صح-ان-صوم-داوود-اتعب-ابن-عمرو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صوم داوود ألم يتعب ابن عمرو.mp3","categories":["صيام التطوع","التاريخ والسيرة"]},{"id":2725,"question":"جزاك الله خيرا يا شيخ، أنت قلت إن أفضل الأعمال الجهاد في سبيل الله واعتزال الناس في شِعْب مِن الشعاب؟","title":"هل أفضل الأعمال الجهاد أم اعتزال الناس؟","answer":"الجواب: عند الفتن، هذا عند الفتن.\nس: اعتزال سعد بن أبي وقاص  الصحابة في عهده، وهو كان في خير القرون؟\nالشيخ: فعل سعد مرجوح.","link":"https://binbaz.org.sa/fatwas/22871/هل-افضل-الاعمال-الجهاد-ام-اعتزال-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أفضل الأعمال الجهاد في سبيل الله أو اعتزال الناس في شعب من الشعاب.mp3","categories":["التاريخ والسيرة"]},{"id":2859,"question":"وقال: لأنه حدث في عهد الرسول ﷺ أن علي بن أبي طالب  عندما أراد أن يتزوج على السيدة فاطمة رضي الله عنها قال له رسول الله ﷺ: إن مِن حق الزوجة الخُلع فهل هذا صحيح، وما هو الخُلع؟","title":"خصوصية عدم الزواج على بنت النبي ﷺ","answer":"الجواب: ليس بصحيح، الله يقول: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً.. [النساء:3] أما قصة فاطمة؛ قصة خاصة تخص فاطمة، لما أراد علي أن يتزوج بنت أبي جهل قال له النبي ﷺ: ما تجتمع بنتي وبنت أبي جهل، إنه يَرِيبُنِي مَا يُرِيبُهَا، وإنها بُضعة مني هذا شيء خاص بفاطمة رضي الله عنها، وإلا فالزواج جائز بثنتين وثلاث وأربع، وليس للزوجة الأولى أن تعترض إلا إذا كانت شرطت عليه ألا يتزوج عليها، فالمسلمون على شروطهم، وأما إذا أحب يتزوج ويعْدِل ويقوم بالواجب؛ فلا بأس، ثنتين أو ثلاث أو أربع.","link":"https://binbaz.org.sa/fatwas/23012/خصوصية-عدم-الزواج-على-بنت-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قصة علي عندما أراد أن يتزوج على السيدة فاطمة.mp3","categories":["التاريخ والسيرة"]},{"id":2944,"question":"هل خَضَب النبي ﷺ لحيته؟","title":"هل خَضَب النبي ﷺ لحيته؟","answer":"الجواب: يُروى أنه كان فيها شعرات وأنه خضبها بالحناء والكَتَم، وخَضَب الصدّيق وعمر رضي الله عنهما، جاء في البخاري عن أنس أن الصديق خضب بالحناء والكَتَم، والنبي ﷺ حين تُوفي ما فيه إلا شعرات قليلة من الشيب.\nس: يقال أن هذا من أثَر الطيب؟\nالشيخ: بعضهم يقول هكذا، لكن فيه نظر.\nس: تخضيب اللحية يعتبر سُنة؟\nالشيخ: ما في شك، سُنة، ما بين الوجوب والسُّنة، النبي عليه الصلاة والسلام قال: غيِّروا هذا الشيب واجتنبوا السواد يقول: إن اليهود والنصارى لا يصبغون فخالفوهم.","link":"https://binbaz.org.sa/fatwas/23100/هل-خضب-النبي-ﷺ-لحيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل خضب النبي لحيته.mp3","categories":["التاريخ والسيرة"]},{"id":3011,"question":"ثبت أيضًا لأبي بكر الصديق الإلهامُ والتحديث؟","title":"هل ثبت لأبي بكر الصدّيق الإلهام والتحديث؟","answer":"الجواب: ما أتذكر شيئًا الآن، وقد يُقال مثل ما قال بعض الصحابة في عهده إلى عمر، لا شك أنه من توفيق الله، وفضل عمر معروف، وأهليته معروفة.","link":"https://binbaz.org.sa/fatwas/23169/هل-ثبت-لابي-بكر-الصديق-الالهام-والتحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ثبت لأبي بكر الصديق الإلهام والتحديث.mp3","categories":["التاريخ والسيرة"]},{"id":3096,"question":"النبي ﷺ هل كان محرمًا لنساء المؤمنين؟","title":"هل كان النبي ﷺ محرمًا لنساء المؤمنين؟","answer":"الجواب: لا ما هو بمحرم.\nس: لأن تجد بعض... أنه كان يتكئ على حِجْر مثل أم سليم رضي الله عنها، أو كان يدخل عليها؟\nالشيخ: لعلها كانت من خالاته رضي الله عنها كما نص العلماء، لعل كان هناك رضاعة، وإلا لم يدل دليل على أنه محرم لنساء المؤمنين.\nس: أم سليم وأم هانئ؟\nالشيخ: أم هانئ بنت عمه، ما فيه أنه خلا بها، وإنما جاءت تسأل.","link":"https://binbaz.org.sa/fatwas/23256/هل-كان-النبي-ﷺ-محرما-لنساء-المومنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل كان النبي محرم لنساء المؤمنين.mp3","categories":["التاريخ والسيرة"]},{"id":3188,"question":"أنواع الوحي، أحسن الله إليك، كم؟","title":"ما أنواع الوحي إلى النبي ﷺ؟","answer":"الجواب: النبي ﷺ يأتيه الوحيُ مِن السماء: تارة يكلمه ربُّه، كما جاء في الحديث؛ فإن محمدًا ﷺ كلمه الله كما كلم موسى.  وتارة يأتي به جبرائيل. وتارة يَسْمَعُه يُقِرُّه المَلَكُ في أُذُنه. فهي ثلاثة أقسام.","link":"https://binbaz.org.sa/fatwas/23351/ما-انواع-الوحي-الى-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كم أنواع الوحي.mp3","categories":["التاريخ والسيرة"]},{"id":3298,"question":"بعض الكتب التي أرسلها النبي ﷺ إلى الأمصار توجد في المتاحف، هل لها شيء من الصحة؟","title":"هل توجد كُتُبٌ مما أرسل النبي ﷺ؟","answer":"الجواب: ما أدري والله، لا يعتمد عليها إلا إذا وُجد مِنْ أهل العلم مَنْ ذكرها، مِنْ أئمة الحديث.","link":"https://binbaz.org.sa/fatwas/23463/هل-توجد-كتب-مما-ارسل-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الكتب التي أرسلها النبي إلى الأمصار هل توجد اليوم بعضًا منها.mp3","categories":["التاريخ والسيرة"]},{"id":3301,"question":"في نسخة: وكان ابن الناظور صاحب إيلياء؟","title":"هل ابن \"الناطور\" بالظاء أو بالطاء المهملة؟","answer":"الجواب: الناطور المعروف، الناطور بالطاء.\nالطالب: قال الشارح: ابن الناطور هو بالطاء المهملة، وفي رواية الحموي بالظاء المعجمة.\nالشيخ: المعروف بالطاء، نعم.","link":"https://binbaz.org.sa/fatwas/23466/هل-ابن-الناطور-بالظاء-او-بالطاء-المهملة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/وكان ابن الناطور، صاحب إيلياء وهرقل.. هل هو بالظاء أو بالطاء المهملة.mp3","categories":["التاريخ والسيرة"]},{"id":3332,"question":"هرقل آمن ثم ارتد، أو لم يؤمن أصلًا وإنما أراد اختبار قومه؟","title":"هل صح أن هرقل آمن ثم ارتد؟","answer":"الجواب: لا، هو صرّح: بأنه نبي، ولو قَدِرت لغَسلت عن قدميه، لكن لمّا رأى إباءهم واستكبارهم حمله حب الرياسة على الرجوع، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/23498/هل-صح-ان-هرقل-امن-ثم-ارتد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل آمن هرقل ثم ارتد، أو لم يؤمن أصلا.mp3","categories":["التاريخ والسيرة"]},{"id":3371,"question":"يقول بعض المفسرين أن الطوفان عَمّ الأرض كلها: يقول: يحتاج هذا إلى دليل، أخبرنا الله أنه أهلك قوم نوح بالطوفان، أما القول بأنه عم الأرض كلها فهذا يحتاج إلى دليل وإثبات؟","title":"هل ثبت أن طوفان نوح عَمّ الأرض كلها؟","answer":"الجواب: الله أعلم، المقصود أن الله أهلك أهل الأرض، إلا من كان في السفينة، أهلك، لكن كونه عمّ الأرض، فما هو بلزوم، المقصود التي فيها سكان أُهلكوا، أما البقاع التي ما فيها أحد قد يكون ما جاءها، لكن الرب جل وعلا أخبر: فَأَخَذَهُمُ الطُّوفَانُ وَهُمْ ظَالِمُونَ [العنكبوت: 14] قال: فَأَنْجَيْنَاهُ وَأَصْحَابَ السَّفِينَةِ [العنكبوت: 14]، ما عداهم لم ينجوا، الذين ما هم في السفينة هلكوا، نسأل الله العافية.\nس: ما ورد في الأرض وَقِيلَ يَا أَرْضُ ابْلَعِي مَاءَكِ [هود: 44] ما يعني أن الأرض....؟\nالشيخ: الله أعلم، المقصود أن الماء عَمّ الناس، عم الكفرة حتى أُهلكوا جميعًا إلا من كان في السفينة، أما كون كل بقعة جاءها الماء وهي ما فيها أحد: الله أعلم.","link":"https://binbaz.org.sa/fatwas/23538/هل-ثبت-ان-طوفان-نوح-عم-الارض-كلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ثبت أن طوفان نوح عمّ الأرض كلها.mp3","categories":["التاريخ والسيرة"]},{"id":3751,"question":"هنا يقول: وعرضه سبعة أذرع، هل هذا صحيح؟","title":"كم طول آدم عليه السلام وعرضه؟","answer":"الجواب: جاء في بعض روايات الترمذي أن آدم طوله ستون ذراعًا في السماء، وعرضه سبعة أذرع؛ لكن في سنده علي بن زيد بن جدعان وفيه بعض الضعف، فالعرض لم يثبت فيه حديث صحيح، إنما جاء من رواية علي بن زيد عند الترمذي والترمذي يصحح له، وهو حسن الرأي فيه، والجمهور يضعفونه.","link":"https://binbaz.org.sa/fatwas/23943/كم-طول-ادم-عليه-السلام-وعرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طول آدم عليه السلام وعرضه.mp3","categories":["التاريخ والسيرة"]},{"id":3758,"question":"بنو إسرائيل كانت فتنتهم في النساء؟","title":"معنى أن فتنة بني إسرائيل كانت في النساء؟","answer":"الجواب: هذا فيما حرم الله يعني.","link":"https://binbaz.org.sa/fatwas/23950/معنى-ان-فتنة-بني-اسراىيل-كانت-في-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فتنة بني إسرائيل كانت في النساء.mp3","categories":["التاريخ والسيرة"]},{"id":3937,"question":"هجر النبي ﷺ لأزواجه شهرًا؟","title":"لماذا هجر النبي ﷺ أزواجه شهرًا؟","answer":"الجواب: هذا هجر النبيﷺ لأنه حق له، معصية منهن. أقول هذه معصية؛ لأن تعديهن عليه وإيذاؤهن له معصية، ولهذا استحقن الهجر زيادة على ثلاثة أيام.","link":"https://binbaz.org.sa/fatwas/24158/لماذا-هجر-النبي-ﷺ-ازواجه-شهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا هجر النبي لأزواجه شهرًا.mp3","categories":["التاريخ والسيرة"]},{"id":3939,"question":"سبب التحالف؟","title":"ما سبب التحالف بين المسلمين أول الهجرة؟","answer":"الجواب: هو ما تقدم، هو تجديد التناصر والتأكيد في التناصر ضد العدو المشترك؛ لأن هؤلاء قدموا عليهم من بلاد غير بلادهم وهم المهاجرون فخيف أن تكون هناك وحشة أو انقسام فآخى النبي ﷺ بينهم على أنهم إخوة في الله، هذا أخو هذا وهذا أخو هذا، بينهم محبة وبينهم التناصر والتوارث، فهم أولى بهذا من أقاربهم، ثم بعد ذلك نسخ هذا الأمر .\nس: يكون نسخ عام؟\nالشيخ: نعم نسخ عام، ما يبقى إلا مودة الإسلام ومحبة الإسلام والموالاة في الإسلام، أما التوارث فهو لأهله القرابات والأصهار .","link":"https://binbaz.org.sa/fatwas/24160/ما-سبب-التحالف-بين-المسلمين-اول-الهجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سبب التحالف والإخاء بين المسلمين في بداية الهجرة.mp3","categories":["التاريخ والسيرة"]},{"id":3972,"question":"أعمال ابن صياد ما توجب قتله؟","title":"لماذا لم يقتل النبي ﷺ ابن صياد؟","answer":"الجواب: النبي ﷺ ما أراد قتله عليه الصلاة والسلام، هو تبع جماعته تبع اليهود، أقرهم في المدينة ووادعهم؛ فلما نقضوا العهد أخرجهم وقتل من قتل، وهم بنو قريظة، وأخرج من أخرج من بني النضير ومن بني قينقاع أخرجهم إلى خيبر وإلى أهل عاد وإلى أطراف الشام، وقتل منهم بني قريظة لما ظاهروا الكفار وساعدوهم يوم الأحزاب.","link":"https://binbaz.org.sa/fatwas/24200/لماذا-لم-يقتل-النبي-ﷺ-ابن-صياد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا لم يقتل النبي ابن صياد.mp3","categories":["التاريخ والسيرة"]},{"id":4033,"question":"ما أصح الأقوال في الفرق بين عبدالله بن عمرو ووالده؟","title":"ما فرق العمر بين عبدالله بن عمرو ووالده؟","answer":"الجواب: وإذا عرفت وأيش الفائدة؟.....  المشهور: بينهما إحدى عشرة أو اثنتا عشرة سنة، كان عمرو تزوج وهو صغير، بينه وبين ولده عبدالله إما إحدى عشرة وإلا اثنتا عشرة، هذا ما سمعنا وما بلغنا، لكن الفائدة هذه قليلة.","link":"https://binbaz.org.sa/fatwas/24269/ما-فرق-العمر-بين-عبدالله-بن-عمرو-ووالده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أصح الأقوال في الفرق بين عبد الله بن عمرو ووالده.mp3","categories":["التاريخ والسيرة"]},{"id":4092,"question":"قولها: \"ما أكل آل محمدٍ ﷺ أكلتين في يومٍ إلا إحداهما تمر\"؟","title":"معنى \"ما أكل آل محمدٍ أكلتين إلا إحداهما تمر\"","answer":"الجواب: الغالب أنه من القلَّة، الغالب أنَّ هذا من القلَّة.","link":"https://binbaz.org.sa/fatwas/24332/معنى-ما-اكل-ال-محمد-اكلتين-الا-احداهما-تمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى ما أكل آل محمدٍ أكلتين في يومٍ إلا إحداهما تمر.mp3","categories":["شروح الحديث","التاريخ والسيرة"]},{"id":4093,"question":"بالنسبة لفعل النبي ﷺ من جهة فراشه ومأكله، هل يُقال أنها من السنة لو فعلها الإنسانُ أحيانًا؟","title":"هل التأسي بتواضع النبيﷺفي معيشته سُنَّة؟","answer":"الجواب: هذا من التواضع، لا شكَّ من التواضع وكسر النفس، إذا فعل الإنسانُ بعض الأشياء التي تُنافي الرفاهية بعض الأحيان لكسر النفس وتعويدها النشاط وتعويدها الخشونة نعم... وسَّع الله عليه وَسَّعوا، مثلما قال عمر: \"إذا وسَّع الله عليكم فوسِّعوا\"، النبي ﷺ إذا صادف شيئًا يسَّره الله له، في زواجه من زينب وضع لحمًا كثيرًا، وطعامًا كثيرًا، ودعا العامَّة عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24333/هل-التاسي-بتواضع-النبيﷺفي-معيشته-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تواضع النبي في مأكله وفراشه.mp3","categories":["الآداب والأخلاق المحمودة","التاريخ والسيرة"]},{"id":4094,"question":"الرسول ﷺ ما كان عنده المال مما أفاء الله؟","title":"هل كان عند الرسول ﷺ مالٌ؟","answer":"الجواب: تارةً وتارةً، تارة يجتمع المال، مثلما حصل بعدما أجلى بني النَّضير حصل له مالٌ كثيرٌ، فكان يعزل نفقته لسنةٍ، والباقي يجعله في الكراع والسلاح عدّة في سبيل الله، وربما كثر عليه الضيوف والوفود فأعطاهم؛ فقلَّ ما عنده عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/24334/هل-كان-عند-الرسول-ﷺ-مال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل كان عند الرسول مالٌ.mp3","categories":["التاريخ والسيرة"]},{"id":4179,"question":"وتيماء تكون من خارج الجزيرة، لما أجلاهم عمر إلى تيماء؟","title":"هل كانت تيماء من الجزيرة زمن إجلاء اليهود؟","answer":"الجواب: يظهر أنها تابعة للشام وهذه من تبع المملكة تيماء وتبوك، ولكن ظاهر الإجلاء لهم إلى تيماء أنها تابعة في ذلك الوقت للشام وكانت في حدود الشام ذاك الوقت ما بعد فتحت، أما الآن فهي تبع الجزيرة.\nالطالب: المحشي قال: هما ممدوتان وهما قريتان معروفتان وفي هذا دليل على أن مراد النبي ﷺ بإخراج اليهود والنصارى من جزيرة العرب إخراجهم من بعضها وهو الحجاز خاصة؛ لأن تيماء من جزيرة العرب لكنها ليست من الحجاز.\nالشيخ: لا، الصواب الجزيرة كلها، الحجاز بعضها، نعم.\nس: لكن خيبر تكون من الجزيرة؟\nالشيخ: نعم خيبر من بطن الجزيرة. ومن الحجاز.\nس: كيف نجمع بينها وبين أمر النبي بإخراجهم من جزيرة العرب؟ \nالشيخ: أخرجهم عمر بعد ذلك.\nالطالب: ذكر القاضي عياض قال: وأريحاء وتيماء قريتان بالشام؟\nالشيخ: على حسب اجتهاده.","link":"https://binbaz.org.sa/fatwas/24436/هل-كانت-تيماء-من-الجزيرة-زمن-اجلاء-اليهود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أجلى عمر بن الخطاب اليهود والنّصارى من أرض الحجاز إلى تيمة.mp3","categories":["شروح الحديث","التاريخ والسيرة"]},{"id":4296,"question":"أبو جهل ابن عم الرسول ﷺ؟","title":"هل لأبي جهل قرابة بالنبي ﷺ؟","answer":"الجواب: ابن عم من بعيد، يجتمعان في الجد الرابع أو الخامس.","link":"https://binbaz.org.sa/fatwas/24569/هل-لابي-جهل-قرابة-بالنبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قرابة أبي جهل من النبي.mp3","categories":["التاريخ والسيرة"]},{"id":4638,"question":"تأخير النبي ﷺ الحج؟","title":"لماذا أخَّر النبي عليه الصلاة والسلام الحج؟","answer":"الجواب: الأقرب والله أعلم أنه لم يُفرض إلا مُتأخِّرًا، أو لأنَّ هناك مشاغل شغلته عن الحجِّ سنة تسعٍ، فأمر أبا بكرٍ كالتَّوطئة.\nس: في السنة التاسعة أمر أبا بكر؟\nج: أن يحجَّ بالناس: إما لأنه تمهيد لحجِّه ﷺ، أو لأنه لم يُفرض ذاك الوقت، أو لم يتمكن ﷺ؛ لأنَّ حجه يحتاج إلى مؤنةٍ لم تتيسر ذاك الوقت، الأصل والقاعدة أنَّ الأوامر على الفور، هذا هو الأصل.","link":"https://binbaz.org.sa/fatwas/24928/لماذا-اخر-النبي-عليه-الصلاة-والسلام-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لماذا أخَّر النبي الحج.mp3","categories":["التاريخ والسيرة"]},{"id":5778,"question":"ذكر بعض المحاضرين أن الرسول ﷺ قال بيتًا من الشعر، فما صحة هذا القول؟","title":"ما صحة حفظ النبي صلى الله عليه وسلم للشعر؟","answer":"الجواب:\n\nهذا البيت صحيح، بس قول الشيخ يغني به، لو أتى بداله قال بيتًا من الشعر وهو قوله:\n\n\n\t\n\t\t\n\t\t\tهل أنتِ إلا إصبع دميت\n\t\t\tوفي سبيل الله ما لقيت\n\t\t\n\t\n\n\nهذا قاله النبي ﷺ ورواه مسلم في الصحيح، رواه مسلم في صحيحه لما حصلت نكبة في إصبعه، ودميت، قال هذا الشعر، عليه الصلاة والسلام.\n\nوقال بعضهم: ولم يحفظ له بيت من الشعر سوى هذا البيت؛ لأن الله قال: وَمَا عَلَّمْنَاهُ الشِّعْرَ وَمَا يَنْبَغِي لَهُ [يس:69] وقال بعض المحدثين: إنه لا يحفظ له بيت من الشعر مستقيم إلا هذا البيت الواحد:\n\n\n\t\n\t\t\n\t\t\tهل أنتِ إلا إصبع دميت ِ\n\t\t\tوفي سبيل الله ما لقيت\n\t\t\n\t\n\nيعني هذا قاله ليظهر صبره، واحتسابه -عليه الصلاة والسلام- وأن هذا الشيء في سبيل الله، فلا بأس عليك أيها الأصبع، ولا يضرك ذلك، وهذا في سبيل الله.","link":"https://binbaz.org.sa/fatwas/1104/ما-صحة-حفظ-النبي-صلى-الله-عليه-وسلم-للشعر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_110.mp3","categories":["التاريخ والسيرة","البدع والمحدثات"]},{"id":6249,"question":"هل أوصى رسول الله ﷺ بأن يقبر في غرفة عائشة، أم الذين حضروه من الصحابة هم الذين اختاروا ذلك؟","title":"تشاور الصحابة في دفن النبي في بيت عائشة","answer":"الجواب: لم يوصهم بشيء في هذا، وإنما الصحابة تشاوروا في هذا، ثم اتفق رأيهم على دفنه في حجرة عائشة حذرًا من الغلو فيه لو أبرز إلى البقيع، خافوا عليه من الغلو، غلو الناس فيه، وإفراطهم؛ فدفنوه في بيت عائشة.  ويروى أن الصديق روى لهم: أنه سمع النبي يقول: إن كل نبي يدفن حيث يموت ولكن لا أعلم الآن صحة هذا الخبر، ولا أذكر حال سنده. والمشهور عند أهل العلم: أنه باتفاق بين الصحابة، وتشاور، فدفنوه بعد ذلك، بعد تشاورة أخوية دفنوه في بيت عائشة؛ حفاظًا عليه، ولهذا قالت عائشة -رضي الله عنها-: ولولا ذلك لأبرز قبره، غير أنه خشي أن يتخذ مسجدًا، فعللت لأنه يخشى أن يتخذ مسجدًا؛ فلهذا دفن في بيتها -رضي الله عنها وأرضاها- هذا هو المشهور.","link":"https://binbaz.org.sa/fatwas/1769/تشاور-الصحابة-في-دفن-النبي-في-بيت-عاىشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_608.mp3","categories":["التاريخ والسيرة"]},{"id":7123,"question":"الأمل كبير في سماحتكم في أن تشفي حيرة الكثيرين، خاصة من الإخوة في مصر، وذلك في موضوع رأس الحسين بن علي  هل هو فعلًا في مصر، أو في العراق جثته ورأسه؟ وما حكم زيارة ضريح السيدة زينب، أو الحسين، أو غيرهما من قبل الرجال فقط؟","title":"حقيقة وجود رأس الحسين بن علي في مصر","answer":"الجواب:\n\nالمعروف عند المحققين أن الموجود في مصر لا حقيقة له، لا رأس ولا غيره، ليس هناك حسين في مصر، وإنما هو غلط في وجود قبر الحسين هناك، لا أصل له، وإنما الحسين دفن في العراق، وقيل: إن رأسه كان في الشام عند يزيد -والله أعلم-. \n\nالمقصود: لا أصل له في مصر، ووجود القبور في مصر التي تعظم من البلايا العظيمة على مصر وأهلها، لا قبر الحسين ولا قبر البدوي، ولا قبر السيدة زينب، ولا السيدة نفيسة، ولا غيرهم من هؤلاء المعظمين، جروا على مصر شرًا كثيرًا بالغلو فيها، ودعوتها من دون الله، والاستغاثة بها، وطلبها المدد حتى وقع العامة في الشرك الأكبر -نعوذ بالله-.\n\nفالواجب على علماء مصر جميعًا -أعني علماء السنة، علماء الحق- الواجب عليهم أن يتقوا الله، وأن يشمروا عن ساعد الجد، وعن الرغبة فيما عند الله، حتى يبصروا الناس، يبصروا العامة بهذا الشرك الأكبر الذي يفعل عند القبور، وعند الطواف، ودعائها، والاستغاثة بها، وقد تواترت عندنا أن حتى صاحب التاكسي إذا مر وقف عند القبر يقول: المدد المدد، ثم يمشي، هذا مما بلغنا وتواتر عندنا. \n\nفالمقصود: أن هذه بلايا عظيمة وقعت في مصر، ووقعت في الشام، ووقعت في الأردن، ووقعت في العراق، وفي بلدان كثيرة.\n\nفالواجب على أهل العلم أن ينشطوا غاية النشاط في نهي العامة عن هذا الشر، وتبصيرهم بالدين كتابة في الصحف، وكتابة في المؤلفات الصغيرة التي تروج بينهم، وفي خطب الجمعة، وفي الخطب التي تكون في المناسبات، وفي المساجد حتى يكثر هذا الأمر بينهم، وحتى يتعلم الجاهل وحتى يعلم بعضهم بعضًا، ويتداولوا هذه الكلمات، وهذه النصائح بينهم.\n\nوهكذا في التسجيل، يسجل أشرطة توزع بينهم حتى يكثر ذلك فيهم، وحتى ينتهوا عن هذا الباطل العظيم، والشرك الوخيم -نعوذ بالله- نسأل الله للعامة الهداية، وللعلماء التوفيق لأداء الواجب.","link":"https://binbaz.org.sa/fatwas/3153/حقيقة-وجود-راس-الحسين-بن-علي-في-مصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1511.mp3","categories":["التاريخ والسيرة","البدع والمحدثات"]},{"id":7450,"question":"نريد أن نخبركم أنه سوف تقام غدًا الجمعة في جامع مصنع الجبس في طريق الخرج صلاة الغائب على فضيلة الشيخ إحسان إلهي ظهير -رحمه الله- نرجو منكم ومن الحاضرين الترحم عليه، والدعاء له بالمغفرة والرحمة وذكر شيئًا من سيرته، والتعريف بحياته للحضور، فالغالب فيهم لا يعرفه جيدًا؟","title":"نبذة عن الشيخ إحسان إلهي ظهير","answer":"الجواب: غفر الله له، ورحمنا وإياه، أخونا الشيخ حافظ إحسان معروف عند خواص أهل العلم، فله مؤلفات كثيرة في الرد على الشيعة، والرد على الوثنية، والرد على غيرهم من طوائف الكفر والضلال، فهو مجاهد -رحمه الله- وقد تخرج من الجامعة الإسلامية في المدينة، واشتغل بالدعوة إلى الله في باكستان، وفي غيرها، وهو يتجول للدعوة إلى الله والتعليم، والرد على خصوم الإسلام، فله مآثر جميلة، ومؤلفات قيمة نافعة، فرحمه الله وأكرم مثواه، يصلى عليه هنا، وإذا صلي عليه في مكة فلا بأس.","link":"https://binbaz.org.sa/fatwas/3535/نبذة-عن-الشيخ-احسان-الهي-ظهير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1839.mp3","categories":["التاريخ والسيرة","البدع والمحدثات"]},{"id":7909,"question":"من مدينة الخرج بعث بهذه الرسالة: سعدون العنزي يقول في رسالته: سماحة الشيخ: عبد العزيز بن عبد الله بن باز الموقر بعد الاحترام والتقدير:السلام عليكم ورحمة الله وبركاته، وبعد:سماحة الشيخ! أرجو إفتائي في السؤال التالي مشكوراً: هل الذي تزوج فاطمة بنت الرسول عليه الصلاة والسلام أبو بكر الصديق أم أنه علي بن أبي طالب رضي الله عنهما جميعاً؟","title":"تزويج فاطمة بنت رسول الله","answer":"الجواب: الذي تزوج فاطمة هو علي بن أبي طالب ، هذا بإجماع المسلمين، ليس في هذا نزاع ولا خلاف، أما أبو بكر الصديق فلم يتزوج بنت النبي ﷺ، ولكن عثمان تزوج ابنتين من النبي ﷺتزوج ابنتيه: رقية وأم كلثوم وماتا في عصمته ، وعلي تزوج الصغيرة وهي فاطمة أم الحسن وأم الحسين رضي الله عن الجميع، وزينب تزوجها أبو العاص بن الربيع ، وهن أربع، وليس في هذا نزاع ولا خلاف.","link":"https://binbaz.org.sa/fatwas/5398/تزويج-فاطمة-بنت-رسول-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06207.mp3","categories":["العالم والمتعلم","التاريخ والسيرة"]},{"id":8606,"question":"هذه رسالةٌ وردتنا من السائل قدري عبدالمنعم، مصري يعمل بالمملكة، يقول: سمعنا في الحديث: لعن الله قومًا اتخذوا قبور أنبيائهم مساجد، ويحدث في كثيرٍ من الأقطار الإسلامية اتخاذ الأضرحة والمقامات لأولياء الله، وعندما ننهى عن ذلك يحتجون بأن قبر النبي ﷺ موجودٌ بمسجده في المدينة المنورة، مما يُحدث عندنا بعض الإشكال.أفيدونا أفادكم الله.","title":"ما الرد على شبهة وجود قبر النبي داخل المسجد؟","answer":"الجواب: لا ريب أن الرسول ﷺ قال: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد، قالت عائشة رضي الله عنها: يُحذِّر ما صنعوا. رواه الشيخان: البخاري ومسلم في \"الصحيحين\". وقال عليه الصلاة والسلام: ألا وإن مَن كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك أخرجه مسلمٌ في \"صحيحه\".\nوهذه الأحاديث وما جاء في معناها كلها واضحةٌ في تحريم اتِّخاذ المساجد على القبور، أو الصلاة عندها، أو القراءة عندها، أو نحو ذلك، ولكن بعض الناس قد تشتبه عليه الأمور، ولا يعرف الحقيقة التي جاء بها المصطفى عليه الصلاة والسلام، فيعمل ما يعمل من البناء على القبور، واتخاذ المساجد عليها؛ جهلًا منه، وقلة بصيرةٍ.\nوأما ما يتعلق بقبر النبي ﷺ فلم يُدفن في ... بالمسجد ﷺ، الرسول ﷺ دُفن في بيت عائشة، ثم وُسِّع المسجد في عهد الوليد بن عبدالملك في آخر القرن الأول، فأُدخلت الحجرة في المسجد، وهذا غلطٌ من الوليد لما أدخلها، وقد أنكر عليه بعض مَن حضره من هناك في المدينة، ولكن لم يُقدر أنه يرعوي لمَن أنكر عليه.\nفالحاصل أن قبر النبي ﷺ كان في البيت -في بيت عائشة رضي الله عنها-، ثم أُدخلت الحجرة -البيت- في المسجد بسبب التوسعة، فلا حُجةَ في ذلك. ثم إنه من فعل الأمير -أمير المؤمنين الوليد بن عبدالملك- وقد أخطأ في ذلك لما أدخله في المسجد. فلا ينبغي لأحدٍ أن يحتج بهذا العمل، فالذي فعله الناس اليوم من البناء على القبور واتخاذ المساجد عليها كله منكرٌ، مخالفٌ لهدي النبي صلى الله عليه وسلم.\nفالواجب على ولاة الأمور من المسلمين إزالته، أي بلدٍ فيها ولي أمرٍ من أمراء المسلمين الواجب عليه أن يُزيل هذه المساجد التي على القبور، وأن يسير على السنة، وأن تكون القبور في الصحراء بارزةً، ليس عليها بناءٌ: لا قباب، ولا مساجد، ولا غير ذلك، كما كانت القبور في عهد النبي ﷺ -في البقيع وغيره- بارزةً، ليس عليها شيءٌ، وهكذا قبور الشهداء -شهداء أحد- لم يكن عليها شيءٌ. فالحاصل أن هذا هو المشروع: أن تكون القبور بارزةً، ضاحيةً، ليس عليها بناءٌ، كما كان في عهد النبي ﷺ وعهد السلف الصالح.\nأما ما أحدثه الناس من البناء فهو بدعةٌ ومنكرٌ، لا يجوز إقراره، ولا التأسي به؛ ولهذا وقع الشرك لما وجد العامَّةُ والجهَّالُ القبور مُشيَّدًا عليها المساجد والقباب، ومُعظَّمة، ومفروشة، ومُطيَّبة؛ ظنوا أنها تقضي حوائجهم، وتشفي مرضاهم، وتنفعهم؛ فدعوها، واستغاثوا بها، ونذروا لها؛ فوقع الشرك -نعوذ بالله- بأسباب ذلك. فالغلو في القبور كله شرٌّ؛ ولهذا قال عليه الصلاة والسلام: إياكم والغلو في الدين، فإنما أهلك مَن كان قبلكم الغلو في الدين، نسأل الله السلامة والعافية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6749/ما-الرد-على-شبهة-وجود-قبر-النبي-داخل-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21015.mp3","categories":["مسائل متفرقة في العقيدة","نواقض الإسلام","التاريخ والسيرة"]},{"id":9171,"question":"هذه رسالة وصلت إلى البرنامج من المستمع عمر الأمين الشيخ، سوداني مقيم بالقصيم، يقول في رسالته: بسم الله الرحمن الرحيم، أرجو الإجابة على سؤالي هذا، عندما كنت أدرس بالمرحلة المتوسطة طرح لنا أحد الأساتذة سؤالاً، وقال فيه: من هو أول رائد للفضاء؟ فأجبنا على سؤاله بأنه سوفييتي الجنسية، وقال لنا الأستاذ: الإجابة خطأ؛ إن أول رائد للفضاء هو: نبينا محمد صلوات الله وسلامه عليه، عندما عرج به إلى السماوات، وكانت مركبتهم البراق، هل هذا صحيح، أفيدونا أفادكم الله؟","title":"ما صحة القول بأن النبي أول رائد فضاء؟","answer":"الجواب: لا نعلم شيئاً في الموضوع غير ما ذكره المجيب، فإنا لا نعلم أحداً عرج به إلى السماء وفرضت عليه الصلوات الخمس سوى نبينا عليه الصلاة والسلام، فإنه عرج به إلى السماء السابعة، حتى كان فوقها؛ وحتى سمع كلام الرب ، فهذا إذا عبر عنه بأنه رائد فضاء؛ فهذا له بعض الوجاهة؛ لكن ليس بصحيح أنه رائد فضاء، بل إنما عرج به إلى السماء إلى ربه عز وجل، ليفرض عليه ما يشاء سبحانه وتعالى، وليس المقصود من هذه الرحلة أن يجوب الفضاء، وأن ينظر في الفضاء، المقصود من هذه الرحلة مع الملك جبرائيل عليه الصلاة والسلام هو أن يرتفع إلى الله، ويجوب السموات، حتى يصل إلى ما فوق السماء السابعة، وحتى يسمع كلام ربه، وليس المقصود أن يجوب الفضاء، فهذا الذي قاله .... له بعض الوجاهة من جهة أن الرسول ﷺ شق الفضاء كله، حتى جاوز السبع الطباق له وجه، لكن ليس هو المعنى المقصود عند الدول الموجودة اليوم؛ أمريكا والسوفيت وغيرهما، مقصودهم: اختبار الفضاء، واختبار ما فيه من العجائب، وليس المقصود هذا المعنى الذي حصل للنبي ﷺ، فالمجيب الذي قال: السوفييتي له وجه، والسائل الذي سألكم لقصده وجه، ولكن ليس منطبقاً على مراد الناس اليوم، وعلى مقصود الناس اليوم، لأن الرسول ﷺ لم يرتحل ليجوب الفضاء، وإنما ارتحل بأمر ربه، ليتصل بالله  فوق السماء السابعة، ويسمع كلامه سبحانه، وليمتثل أمره جل وعلا، فالرسول ﷺ مأمور بأن يرتحل هذه الرحلة العظيمة، ويسمع كلام ربه، وليفرض الله عليه هذه الصلوات العظيمة؛ التي هي أعظم أركان الإسلام بعد الشهادتين، والله ولي التوفيق.","link":"https://binbaz.org.sa/fatwas/7331/ما-صحة-القول-بان-النبي-اول-راىد-فضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_232/23213.mp3","categories":["العالم والمتعلم","التاريخ والسيرة"]},{"id":9777,"question":"يقول أيضاً نفس السائل: في نفس الكتاب يذكر المؤلف أن أحد كتاب الوحي ارتد عن الإسلام، والسبب أنه كان يكتب ما ينزل عليه من الآيات كقوله تعالى: الْعَزِيزُ الْحَكِيمُ [البقرة:129] يكتبها: العليم الحكيم، أو نحو ذلك، وفي الحقيقة لم أفهم مقصود المؤلف أرجو الإيضاح؟","title":"هل ارتد أحد من كتاب الوحي؟","answer":"الجواب: أنا لا أذكر بحث المؤلف، ويمكن أن نطالعه في وقت مستقبل إن شاء الله لا نذكر بحثه، لكن ارتداد بعض كتاب الوحي واقع هو عبد الله بن سعد بن أبي سرح ارتد عن الإسلام ثم دخل في الإسلام وهداه الله يوم الفتح، أما الأسباب أسباب الردة فلا أذكرها حالياً، ولكن يمكن أن نراجع كلام ابن القيم وأن أذكر ذلك في حلقة أخرى إن شاء الله.\nوأما قوله: إن بعض كتاب الوحي ارتد فهذا معروف هو عبد الله بن سعد بن أبي سرح ارتد عن الإسلام ثم بعدما فتح الله على رسوله مكة هداه الله وجاء وأسلم، والحمد لله. نعم.\nالمقدم: بارك الله فيكم. وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7946/هل-ارتد-احد-من-كتاب-الوحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_258/25807.mp3","categories":["العالم والمتعلم","التاريخ والسيرة"]},{"id":10051,"question":"أرجو إرشادي إلى أسماء كتب طيبة تتحدث عن قصص الأنبياء وعن قصص الصحابة ؟","title":"الكتب التي تتحدث عن سير الأنبياء والصحابة","answer":"الجواب: أرشدك أولاً إلى أن تهتمي بالقرآن العظيم فهو أعظم القصص وأحسن القصص، قال فيه جل وعلا: نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ [يوسف:3]، فيه قصص عن الأنبياء وأممهم وعن أهل الخير والشر، فهو أعظم كتاب وأحسن كتاب وأصدق كتاب فأوصيك بالقرآن كثيراً وأن تعتني بالإكثار من تلاوته وتدبر معانيه، ثم بعد ذلك من أحسن الكتب في هذا الباب (زاد المعاد) لـابن القيم في هدي خير العباد، والمجلدات الأولى من تاريخ ابن كثير في قصص النبي ﷺ وأخباره وأخبار الصحابة وكتابه كله طيب (البداية والنهاية) كله طيب، وهناك كتاب مختصر للسيوطي سماه تاريخ الخلفاء فيه فائدة طيبة، وأوصيك أيضاً بحفظ كتاب \"التوحيد\" للشيخ محمد عبد الوهاب (والعقيدة الواسطية) لشيخ الإسلام ابن تيمية، وثلاثة الأصول للشيخ محمد، كشف الشبهات، وآداب المشي إلى الصلاة، كلها كتب مفيدة، كذلك أوصيك بمطالعة فتح المجيد شرح كتاب التوحيد فهو كتاب جيد مفيد، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/8221/الكتب-التي-تتحدث-عن-سير-الانبياء-والصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30305.mp3","categories":["التاريخ والسيرة","العالم والمتعلم"]},{"id":10058,"question":"أرجو إرشادي إلى أسماء كتب طيبة تتحدث عن قصص الأنبياء وعن قصص الصحابة ؟","title":"الكتب التي تتحدث عن سير الأنبياء والصحابة","answer":"الجواب: أرشدك أولاً إلى أن تهتمي بالقرآن العظيم فهو أعظم القصص وأحسن القصص، قال فيه جل وعلا: نَحْنُ نَقُصُّ عَلَيْكَ أَحْسَنَ الْقَصَصِ [يوسف:3]، فيه قصص عن الأنبياء وأممهم وعن أهل الخير والشر، فهو أعظم كتاب وأحسن كتاب وأصدق كتاب فأوصيك بالقرآن كثيراً وأن تعتني بالإكثار من تلاوته وتدبر معانيه، ثم بعد ذلك من أحسن الكتب في هذا الباب (زاد المعاد) لـابن القيم في هدي خير العباد، والمجلدات الأولى من تاريخ ابن كثير في قصص النبي ﷺ وأخباره وأخبار الصحابة وكتابه كله طيب (البداية والنهاية) كله طيب، وهناك كتاب مختصر للسيوطي سماه تاريخ الخلفاء فيه فائدة طيبة، وأوصيك أيضاً بحفظ كتاب \"التوحيد\" للشيخ محمد عبد الوهاب (والعقيدة الواسطية) لشيخ الإسلام ابن تيمية، وثلاثة الأصول للشيخ محمد، كشف الشبهات، وآداب المشي إلى الصلاة، كلها كتب مفيدة، كذلك أوصيك بمطالعة فتح المجيد شرح كتاب التوحيد فهو كتاب جيد مفيد، وفق الله الجميع. نعم.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/8221/الكتب-التي-تتحدث-عن-سير-الانبياء-والصحابة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_303/30305.mp3","categories":["التاريخ والسيرة","العالم والمتعلم"]},{"id":10407,"question":"كيف صيام عاشوراء؟ وكيف صيام أيام هجرة الرسول ﷺ؟ وهل يجوز صيام اليوم العاشر منه؟ أرجو توضيح ذلك جزاكم الله خيرًا؟","title":"حكم صيام يوم عاشوراء وأيام الهجرة","answer":"الجواب: أما صيام عاشوراء فالسنة أن يصوم الإنسان اليوم العاشر من المحرم، وأن يصوم معه يومًا قبله أو يومًا بعده، والأفضل أن يصوم التاسع مع العاشر، لقول النبي ﷺ: لئن عشت إلى قابل لأصومن التاسع يعني: مع العاشر، والمروي عنه عليه الصلاة والسلام أنه قال: خالفوا اليهود وصوموا يومًا قبله أو يومًا بعده.\nفالسنة للمؤمن أن يصوم التاسع والعاشر جميعًا أو يصوم العاشر ومعه الحادي عشر، أو يصوم الثلاثة جميعًا التاسع والعاشر والحادي عشر، كل هذا فيه مخالفة لليهود، والمؤمن يخالفهم يعني: مأمور بمخالفة أعداء الله من أهل الكتاب ومن غيرهم من الكفرة.\nأما أيام الهجرة فلا يشرع صيامها، ولم يصم النبي ﷺ أيام الهجرة لا اليوم الأول ولا غيره، وهكذا يوم بدر، وأيام الأحزاب كلها لا تصام، وهكذا يوم الفتح كلها لم يشرع الله صيامها ، وإنما شرع لنا صيام يوم عاشوراء، صيام الإثنين والخميس، صيام ثلاثة أيام من كل شهر، وإذا صامها في أيام البيض كان أفضل، صيام ست من شوال بعد رمضان، كل هذه أمور مستحبة، أما أيام الهجرة فلا يشرع صيامها بل يكون بدعة إذا قصد ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8580/حكم-صيام-يوم-عاشوراء-وايام-الهجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34014.mp3","categories":["التاريخ والسيرة","صيام التطوع"]},{"id":10617,"question":"نقرأ في بعض الكتب كلاماً يدس فيه على الإسلام، كما قيل عن عزل خالد بن الوليد  عن قيادة الجيش، حبذا لو نبهتم الناس سماحة الشيخ إلى تلكم المقولات التي تطعن في الإسلام وفي خالد بن الوليد؟","title":"ما سبب عزل عمر لخالد بن الوليد وتوليته لأبي عبيدة؟","answer":"الجواب: المعروف في هذا أن عزله من عمر كان لأمر سياسي رآه ، ورأى إبداله بـأبي عبيدة بن الجراح، لأمر رآه كفيلاً بالمصلحة للمسلمين.\nوقال بعض أهل العلم: إن السبب في ذلك: إن عمر كان  قوياً في كل الأمور، وكان خالد كذلك قوياً في بعض الأمور، فناسب أن يكون أبو عبيدة هو أمير عمر؛ لأنه كان ليناً رفيقاً، ليس مثل خالد في الشدة، حتى يعتدل الأمر، يكون أبو عبيدة مع لينه في مقابل شدة عمر ، وكان خالد في قوته في مقابل لين الصديق  فاعتدل الأمر، وهذا كلام وجيه وليس بالبعيد.\nوالحاصل: أن عمر  إنما عزله لأمر سياسي لمصلحة المسلمين، إما ما ذكرنا وإما غيره، والمشهور هو ما ذكرنا، والله ولي التوفيق.\nالمقدم: جزاكم الله خيراً، إذاً لا يلتفت إلى تلك الأقوال التي تدس في هذه ...\nالشيخ: كل ما خالف ذلك من الظن السوء كله باطل، كل ما يقال من ظن السوء في عمر أو في خالد كله باطل.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8790/ما-سبب-عزل-عمر-لخالد-بن-الوليد-وتوليته-لابي-عبيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32702.mp3","categories":["التاريخ والسيرة"]},{"id":10799,"question":"يسأل سؤالًا آخر فيقول فيه: أين أقيمت أول جمعة في الإسلام؟ ومن الذي خطب الخطبة فيها، وصلى بالناس؟","title":"أول جمعة أقيمت في الإسلام","answer":"الجواب:  أول جمعة في المدينة، صلى بالناس أسعد  وكان ذلك قبل أن يهاجر النبي ﷺ كان جمع الناس، وصلى بهم في الخضبات، موضع معروف في المدينة، وأول جمعة في غير المدينة في جواثى قرية في مجمع البحرين، وهذا هو المعروف في السير وكتب الحديث، ثم هاجر النبي ﷺ وصار يقيمها في مسجده -عليه الصلاة السلام- نعم أسعد بن زرارة إي نعم.. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8973/اول-جمعة-اقيمت-في-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_352/35203.mp3","categories":["التاريخ والسيرة"]},{"id":11218,"question":"تقول: يتردد على ألسنة بعض العامة أن أحب الطعام إلى النبي ﷺ هو الكوسة، هل هذا صحيح؟","title":"ما مدى صحة أن الكوسة أحب الطعام للنبي؟","answer":"الجواب:  لا نعرف هذا، ولا أصل لهذا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9418/ما-مدى-صحة-ان-الكوسة-احب-الطعام-للنبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37316.mp3","categories":["التاريخ والسيرة"]},{"id":11611,"question":"يوجد بعض الناس الذين يقولون: بأن الرسول ﷺ أسري به، ولم يعرج به إلى السماء؛ وذلك لأن الإسراء ذكر في القرآن الكريم، والمعراج لم يذكر ما هو توجيه سماحتكم؟ جزاكم الله خيرًا.","title":"حكم من ينكر المعراج لأنه لم يذكر في القرآن","answer":"الجواب:  الإسراء ثابت بالقرآن والسنة، والمعراج ثبت بالسنة المتواترة عن النبي -عليه الصلاة والسلام- أنه عرج به إلى السماء، وجاوز السبع الطباق، وجاوز السماء السابعة حتى صار إلى موضع يسمع فيه صريف الأقلام، وسمع من ربه -جل وعلا- فرضية الصلوات الخمس، فمن أنكر ذلك يعرف ويبين له الأدلة الشرعية، فإذا أصر، وأنكرها؛ كفر -نسأل الله العافية- نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9793/حكم-من-ينكر-المعراج-لانه-لم-يذكر-في-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38804.mp3","categories":["مسائل متفرقة في العقيدة","التاريخ والسيرة"]},{"id":12318,"question":"المستمع محمود عبدالقادر رديالوا سنغالي ومقيم في جامبيا يقول: أرجو أن تحدثونا عن الشيخ محمد بن عبدالوهاب، وعن دعوته، وعن سيرته، وأبرز مؤلفاته جزاكم الله خيرًا.","title":"التعريف بالشيخ محمد بن عبدالوهاب ودعوته","answer":"الجواب:  الشيخ محمد -رحمه الله- إمام كبير، وعلامة شهير، من الله عليه بالفقه في الدين، والبصيرة في علوم الشريعة، ولا سيما العقيدة الصحيحة -عقيدة أهل السنة والجماعة - وكان ذلك في وسط القرن الثاني عشر، تعلم على علماء بلده، وسافر إلى مكة والمدينة، وأخذ عن بعض علمائهما. ثم رجع إلى بلده الدرعية، ورأى أن الناس ... التعلق بالأموات والقبور والشجر والحجر، ففتح الله عليه، ومن عليه بالقوة والصبر، فدعا إلى الله، وأرشد الناس إلى توحيد الله، وعلمهم أن التعلق بالقبور والأشجار والأحجار والاستغاثة بها شرك أكبر، وصبر على ذلك، وعاداه كثير من أهل زمانه، ولكن الله نصره عليهم، وتابعه جم غفير من أهل العلم والبصيرة من أقاربه وغيرهم، فصارت دعوته فتحًا عظيمًا على المسلمين، ورحمة من الله لعباده في هذه الجزيرة العربية، وكانت دعوته أولًا في الحريملاء. ثم انتقل إلى العيينة كلها قرى .... متقاربة، ومكث في .... مدة أيضًا عند أميرها عثمان بن معمر يدعو إلى الله، ويعلم الناس شريعة الله، ويحذرهم من الشرك بالله، وعبادة غيره، وكانت قبة زيد بن الخطاب في الجبيلة معظمة، تدعى من دون الله، كان يدعى من دون الله ويعبد؛ لأنه قتل في يوم اليمامة في قتال مسيلمة، وصار الناس يعظمون قبره، ويدعونه من دون الله، وعليه بنية، فأعان الله الشيخ، وذهب بجماعة من العيينة، وهدموا تلك القبة، وبين للناس أن هذا لا يجوز، وأن البناء على القبور لا يجوز، وأن دعاء الميت، والاستغاثة به لا يجوز، ولم يزل في الدعوة إلى الله، وإرشاد الناس إلى توحيد الله، وإلى ما شرعه الله من الأوامر، وإلى ترك ما حرم الله من المعاصي، من الزنا والسرقة والربا وشرب المسكرات إلى غير ذلك. وتابعه على ذلك جم غفير من العلماء من أبنائه، وأقربائه وغيرهم، فهو بحمد الله نعمة من الله، فتح الله به القلوب، وفتح الله به البلاد؛ حتى دخل الناس في دين الله أفواجًا بعدما اتضحت لهم الدعوة، وقام آل سعود وناصروه، وعلى رأسهم الإمام محمد بن سعود الأمير في زمانه، فإنه كان بالعيينة أولًا، ثم صار بينه وبين عثمان بن معمر بعض الشيء، فخرج من العيينة إلى الدرعية، وتلقاه الأمير محمد بن سعود أمير الدرعية، وبايعه على النصرة والجهاد؛ فوفى له بذلك، الأمير محمد وفى بما قال، وتساعدا في الدعوة، وقام سوق الجهاد في سبيل الله؛ حتى أظهر الله الحق، ونصر الحق، ودخل الناس في دين الله أفواجًا، وانتشرت الدعوة في هذه الجزيرة.  ثم فتح الله على آل سعود مكة والمدينة، وأظهرا فيها العقيدة الصحيحة، وهدما ما على القبور من البنايات، من القباب وغير ذلك في مكة والمدينة، وأوضحوا للناس حقيقة التوحيد، وكان فتح مكة والمدينة على آل سعود بعد موت الشيخ -رحمه الله- في السنة الثامنة عشرة من الهجرة، بعد القرن الثاني عشر ... عام ثماني عشرة ومائتين وألف، وكان الشيخ توفي رحمه الله سنة ست ومائتين. والمقصود: أن دعوة الشيخ محمد دعوة سلفية، دعوة صحيحة، وهو إمام محقق، فتح الله عليه في هذا الباب، ودعا إلى الله، وأرشد إلى الله، وصبر على الأذى، وعلى معاداة من عاداه من أقاربه وغيرهم؛ حتى نصره الله عليهم، وحتى أظهر الله الحق على يديه، ثم على يدي أبنائه بعده، وعلى يدي الأمراء من آل سعود، فجزاهم الله جميعًا خيرًا، ورحمهم رحمة واسعة، وضاعف لهم المثوبة. ولم تزل هذه الدعوة -بحمد الله- قائمة على يدي آل الشيخ، وآل سعود، وعلى يدي العلماء، علماء الشريعة علماء العقيدة، من علماء الجزيرة، يدعون إلى الله، ويعلمون الناس دين الله. وهكذا انتشرت في خارج الجزيرة في الشام والعراق ومصر وفي الهند وغيرها، نقلها العلماء إلى هذه البلدان، ونفع الله بها من شاء من العباد، وذلك بتوفيق من الله، ورحمة من الله لمن نقلها، ولمن نقلت إليه. وهو -رحمه الله- صبور على الأذى، وهكذا أتباعه صبروا كثيرًا، وأوذوا كثيرًا، وقتل من قتل من أتباعه، ولكنهم لم يتأخروا عن جهاد أعداء الله، ولم يتأخروا عن الدعوة، فصبروا، وجاهدوا حتى فتح الله عليهم بلاد الجزيرة ..... النجدية كلها، وهكذا فتح الله عليهم الحجاز، الحرمين وبقية بلاد الحجاز، كل ذلك من فضل الله عليهم، من فضل الله عليهم لما نصروا دينه، وأرشدوا العباد إلى ما يجب عليهم، وصبروا على الأذى، فتح الله عليهم، ونفع الله بدعوتهم، وانتشرت أيضًا في اليمن هذه الدعوة، وانتفع بها الكثير من اليمن. وله من المؤلفات رسائل كثيرة جمعت في مجموع الرسائل والفتاوى مجتمع المسمى السنية المطبوع الموزع بين الناس، وله كتاب التوحيد كتاب عظيم، ألفه في أول الدعوة، وانتشر، وله ثلاثة الأصول، والقواعد الأربع، كتاب صغير مفيد جدًا، وله أيضًا كشف الشبهات، أوضح فيها بطلان الشبهات التي تشبث بها أعداء الله من عباد الأوثان، وله كتاب في الصلاة والزكاة والصيام، المسمى آداب المشي إلى الصلاة، وله رسائل كثيرة -رحمه الله- طبعت في المجموع الذي سمعت. المقدم: الذي هو الدرر؟ الشيخ: السنية نعم. المقدم: بارك الله فيكم، هل هذا الكتاب منتشر في كل مكان سماحة الشيخ؟ الشيخ: نعم مطبوع ... توزعه الحكومة، توزعه دار الإفتاء ... سابقًا، وتوزعه وزارة الشؤون الإسلامية أيضًا. المقدم: هل هو منتشر على نطاق تجاري؟ الشيخ: نعم منتشر، يوزع منذ مدة طويلة في الداخل والخارج، نعم. المقدم: بارك الله فيكم، من أراد شراءه يتمكن سماحة الشيخ؟ الشيخ: يبيعونها أولاد الشيخ ..... أولاده يبيعونه، ودار الإفتاء توزعه، والآن انتقل التوزيع إلى وزارة الشئون الإسلامية التي يقوم عليها معالي الوزير الدكتور عبد الله بن عبدالمحسن التركي .... نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10515/التعريف-بالشيخ-محمد-بن-عبدالوهاب-ودعوته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39803.mp3","categories":["التاريخ والسيرة"]},{"id":12322,"question":"المستمع محمود عبدالقادر رديالوا سنغالي ومقيم في جامبيا يقول: أرجو أن تحدثونا عن الشيخ محمد بن عبدالوهاب، وعن دعوته، وعن سيرته، وأبرز مؤلفاته جزاكم الله خيرًا.","title":"التعريف بالشيخ محمد بن عبدالوهاب ودعوته","answer":"الجواب:  الشيخ محمد -رحمه الله- إمام كبير، وعلامة شهير، من الله عليه بالفقه في الدين، والبصيرة في علوم الشريعة، ولا سيما العقيدة الصحيحة -عقيدة أهل السنة والجماعة - وكان ذلك في وسط القرن الثاني عشر، تعلم على علماء بلده، وسافر إلى مكة والمدينة، وأخذ عن بعض علمائهما. ثم رجع إلى بلده الدرعية، ورأى أن الناس ... التعلق بالأموات والقبور والشجر والحجر، ففتح الله عليه، ومن عليه بالقوة والصبر، فدعا إلى الله، وأرشد الناس إلى توحيد الله، وعلمهم أن التعلق بالقبور والأشجار والأحجار والاستغاثة بها شرك أكبر، وصبر على ذلك، وعاداه كثير من أهل زمانه، ولكن الله نصره عليهم، وتابعه جم غفير من أهل العلم والبصيرة من أقاربه وغيرهم، فصارت دعوته فتحًا عظيمًا على المسلمين، ورحمة من الله لعباده في هذه الجزيرة العربية، وكانت دعوته أولًا في الحريملاء. ثم انتقل إلى العيينة كلها قرى .... متقاربة، ومكث في .... مدة أيضًا عند أميرها عثمان بن معمر يدعو إلى الله، ويعلم الناس شريعة الله، ويحذرهم من الشرك بالله، وعبادة غيره، وكانت قبة زيد بن الخطاب في الجبيلة معظمة، تدعى من دون الله، كان يدعى من دون الله ويعبد؛ لأنه قتل في يوم اليمامة في قتال مسيلمة، وصار الناس يعظمون قبره، ويدعونه من دون الله، وعليه بنية، فأعان الله الشيخ، وذهب بجماعة من العيينة، وهدموا تلك القبة، وبين للناس أن هذا لا يجوز، وأن البناء على القبور لا يجوز، وأن دعاء الميت، والاستغاثة به لا يجوز، ولم يزل في الدعوة إلى الله، وإرشاد الناس إلى توحيد الله، وإلى ما شرعه الله من الأوامر، وإلى ترك ما حرم الله من المعاصي، من الزنا والسرقة والربا وشرب المسكرات إلى غير ذلك. وتابعه على ذلك جم غفير من العلماء من أبنائه، وأقربائه وغيرهم، فهو بحمد الله نعمة من الله، فتح الله به القلوب، وفتح الله به البلاد؛ حتى دخل الناس في دين الله أفواجًا بعدما اتضحت لهم الدعوة، وقام آل سعود وناصروه، وعلى رأسهم الإمام محمد بن سعود الأمير في زمانه، فإنه كان بالعيينة أولًا، ثم صار بينه وبين عثمان بن معمر بعض الشيء، فخرج من العيينة إلى الدرعية، وتلقاه الأمير محمد بن سعود أمير الدرعية، وبايعه على النصرة والجهاد؛ فوفى له بذلك، الأمير محمد وفى بما قال، وتساعدا في الدعوة، وقام سوق الجهاد في سبيل الله؛ حتى أظهر الله الحق، ونصر الحق، ودخل الناس في دين الله أفواجًا، وانتشرت الدعوة في هذه الجزيرة.  ثم فتح الله على آل سعود مكة والمدينة، وأظهرا فيها العقيدة الصحيحة، وهدما ما على القبور من البنايات، من القباب وغير ذلك في مكة والمدينة، وأوضحوا للناس حقيقة التوحيد، وكان فتح مكة والمدينة على آل سعود بعد موت الشيخ -رحمه الله- في السنة الثامنة عشرة من الهجرة، بعد القرن الثاني عشر ... عام ثماني عشرة ومائتين وألف، وكان الشيخ توفي رحمه الله سنة ست ومائتين. والمقصود: أن دعوة الشيخ محمد دعوة سلفية، دعوة صحيحة، وهو إمام محقق، فتح الله عليه في هذا الباب، ودعا إلى الله، وأرشد إلى الله، وصبر على الأذى، وعلى معاداة من عاداه من أقاربه وغيرهم؛ حتى نصره الله عليهم، وحتى أظهر الله الحق على يديه، ثم على يدي أبنائه بعده، وعلى يدي الأمراء من آل سعود، فجزاهم الله جميعًا خيرًا، ورحمهم رحمة واسعة، وضاعف لهم المثوبة. ولم تزل هذه الدعوة -بحمد الله- قائمة على يدي آل الشيخ، وآل سعود، وعلى يدي العلماء، علماء الشريعة علماء العقيدة، من علماء الجزيرة، يدعون إلى الله، ويعلمون الناس دين الله. وهكذا انتشرت في خارج الجزيرة في الشام والعراق ومصر وفي الهند وغيرها، نقلها العلماء إلى هذه البلدان، ونفع الله بها من شاء من العباد، وذلك بتوفيق من الله، ورحمة من الله لمن نقلها، ولمن نقلت إليه. وهو -رحمه الله- صبور على الأذى، وهكذا أتباعه صبروا كثيرًا، وأوذوا كثيرًا، وقتل من قتل من أتباعه، ولكنهم لم يتأخروا عن جهاد أعداء الله، ولم يتأخروا عن الدعوة، فصبروا، وجاهدوا حتى فتح الله عليهم بلاد الجزيرة ..... النجدية كلها، وهكذا فتح الله عليهم الحجاز، الحرمين وبقية بلاد الحجاز، كل ذلك من فضل الله عليهم، من فضل الله عليهم لما نصروا دينه، وأرشدوا العباد إلى ما يجب عليهم، وصبروا على الأذى، فتح الله عليهم، ونفع الله بدعوتهم، وانتشرت أيضًا في اليمن هذه الدعوة، وانتفع بها الكثير من اليمن. وله من المؤلفات رسائل كثيرة جمعت في مجموع الرسائل والفتاوى مجتمع المسمى السنية المطبوع الموزع بين الناس، وله كتاب التوحيد كتاب عظيم، ألفه في أول الدعوة، وانتشر، وله ثلاثة الأصول، والقواعد الأربع، كتاب صغير مفيد جدًا، وله أيضًا كشف الشبهات، أوضح فيها بطلان الشبهات التي تشبث بها أعداء الله من عباد الأوثان، وله كتاب في الصلاة والزكاة والصيام، المسمى آداب المشي إلى الصلاة، وله رسائل كثيرة -رحمه الله- طبعت في المجموع الذي سمعت. المقدم: الذي هو الدرر؟ الشيخ: السنية نعم. المقدم: بارك الله فيكم، هل هذا الكتاب منتشر في كل مكان سماحة الشيخ؟ الشيخ: نعم مطبوع ... توزعه الحكومة، توزعه دار الإفتاء ... سابقًا، وتوزعه وزارة الشؤون الإسلامية أيضًا. المقدم: هل هو منتشر على نطاق تجاري؟ الشيخ: نعم منتشر، يوزع منذ مدة طويلة في الداخل والخارج، نعم. المقدم: بارك الله فيكم، من أراد شراءه يتمكن سماحة الشيخ؟ الشيخ: يبيعونها أولاد الشيخ ..... أولاده يبيعونه، ودار الإفتاء توزعه، والآن انتقل التوزيع إلى وزارة الشئون الإسلامية التي يقوم عليها معالي الوزير الدكتور عبد الله بن عبدالمحسن التركي .... نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10515/التعريف-بالشيخ-محمد-بن-عبدالوهاب-ودعوته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39803.mp3","categories":["التاريخ والسيرة"]},{"id":12389,"question":"هل الرسول -عليه الصلاة والسلام- كان يحتجم في كل عام؟","title":"هل كان يحتجم الرسول في كل عام؟","answer":"الجواب:  ثبت عنه ﷺ أنه احتجم، أما كونه في كل عام لا أعلم شيئًا في هذا، لا أذكر شيئًا في هذا، يعني: ثبت عنه أنه كان يحتجم، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/10590/هل-كان-يحتجم-الرسول-في-كل-عام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40109.mp3","categories":["التاريخ والسيرة"]},{"id":12836,"question":"سؤال آخر لنفس صاحب الرسالة يقول: قرأت أن الرسول -عليه أفضل الصلاة والسلام- تعرض للسحر، هل هذا صحيح؟","title":"حقيقة تعرض الرسول عليه الصلاة والسلام للسحر","answer":"الجواب:  نعم، تعرض للسحر، ولكن الله عافاه منه، ولم يؤثر في رسالته ولا فيما بلغه الأمة، إنما أثر شيئًا فيما بينه وبين أهله، بعض اليسير، ثم أزال الله ذلك والحمد لله، ولم يتأثر به في شيء من أمر الرسالة والبلاغ، والحمد لله؛ لأنه معصوم في ذلك، قد أجمع العلماء على أنه معصوم في كل ما يبلغه عن الله في شريعته وأحكامه، وأن السحر الذي حصل له لم يضره شيء في هذا الباب، ولم يؤثر بشيء والحمد لله، نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/11050/حقيقة-تعرض-الرسول-عليه-الصلاة-والسلام-للسحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46402.mp3","categories":["التاريخ والسيرة"]},{"id":12956,"question":"يقول هذا السائل: ما هي قصة مقام إبراهيم  وحجر إسماعيل -عليهما الصلاة والسلام-؟ أفيدونا يا سماحة الشيخ.","title":"قصة مقام إبراهيم وحجر إسماعيل عليهما السلام","answer":"الجواب:  مقام إبراهيم؛ حجر كان يقوم عليه يبني، فلما فرغ جعله تحت جدار الكعبة، فلما بعث النبي ﷺ أمر بأن يصلى خلفه، أمره الله: وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى [البقرة:125] وكان قرب الكعبة، فأخره عمر في مكانه المعروف. المقصود: أنه حجر كان يقوم عليه إبراهيم للبناء -عليه الصلاة والسلام- هذا مقام إبراهيم. سؤاله الثاني عن إيش؟ المقدم: يقول: حجر إسماعيل ؟ الشيخ: أما الحجر فهذا قطعة من الكعبة لما عمرت قريش الكعبة قصرت بهم النفقة، فأخرجوا بعض البيت وكانت قريش جمعت أموالًا كثيرة من أكساب طيبة، وأبعدت عن النفقة الأكساب الخبيثة، كمهر البغي، والربا، ونحو ذلك، وجمعوا أكسابًا طيبة لبناء الكعبة، فقصرت بهم النفقة؛ فأخرجوا الحجر، ومعظمه وأكثره من الكعبة من عند المنحنى، نحو سبعة أذرع، هذا من الكعبة، قال النبي ﷺ لعائشة: صلي في الحجر فإنه من البيت نعم. أما قول بعض الناس: إن فيه أمواتًا، وإن إبراهيم مدفون فيه، أو ما أشبهه، هذا كله باطل، ليس فيه أموات لا إسماعيل ولا غيره، هذا من خرافات الإسرائيلين، وبعض التاريخ التي لا تبالي، فالحجر ليس فيه أموات، والمسجد ليس فيه أموات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11173/قصة-مقام-ابراهيم-وحجر-اسماعيل-عليهما-السلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50213.mp3","categories":["التاريخ والسيرة"]},{"id":12978,"question":"هذا السائل (ع. أ. أ) الرياض يقول: هل كان الإسراء بالنبي ﷺ بالجسد والروح، أم بالروح فقط؟ وجهونا بهذا السؤال؟","title":"ثبوت إسراء النبي وعروجه بروحه وجسده","answer":"الجواب:  كان الإسراء بالجسد والروح جميعًا -عليه الصلاة والسلام- أسري بجسده وروحه مكة إلى الشام إلى سوريا، ومنها إلى السماء، عرج به إلى السماء حتى جاوز السبع الطباق، حتى جاوز السماء السابعة، وانتهى إلى موضع يسمع فيه صريف الأقلام، وكلمه ربه، وفرض عليه الصلوات الخمس . فالمقصود أنه: أسري بروحه وجسده من مكة إلى الشام، ثم عرج به من الشام، إلى السماء بروحه وجسده -عليه الصلاة والسلام- هذا هو الصواب الذي عليه عامة أهل العلم، والقول بأنه بالروح قول شاذ، مخالف للآية الكريمة، وللأحاديث الصحيحة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11195/ثبوت-اسراء-النبي-وعروجه-بروحه-وجسده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50309.mp3","categories":["مسائل متفرقة في العقيدة","التاريخ والسيرة"]},{"id":13708,"question":"تقول هذه السائلة من اليمن سماحة الشيخ في سؤالها الثاني: لماذا سميت ابنة الرسول ﷺ بفاطمة الزهراء؟","title":"سبب تسمية فاطمة بالزهراء","answer":"الجواب: لا أعلم، الله أعلم، لا أعلم وقتي ايش هي العلة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12072/سبب-تسمية-فاطمة-بالزهراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54504.mp3","categories":["التاريخ والسيرة"]},{"id":13711,"question":"في آخر أسئلة هذه السائلة من اليمن تسأل وتقول سماحة الشيخ: كم عدد زوجات الرسول ﷺ؟","title":"عدد زوجات الرسول عليه الصلاة والسلام","answer":"الجواب: زوجاته تسع التي مات عنهن، اللاتي مات عنهن وهم في عصمته تسع نساء -رضي الله عنهن وأرضاهن- والله أباح له ذلك خاصة، أما الأمة فليس لها الزيادة على أربع فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ [النساء:3] الأمة مقصورة على أربع، أما هو ﷺ فقد أباح الله له أكثر من ذلك، ومات عن تسع -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12078/عدد-زوجات-الرسول-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54506.mp3","categories":["التاريخ والسيرة"]},{"id":13770,"question":"أخونا إبراهيم أبو حامد في سؤاله الثاني يقول: ما هي فضائل خديجة -رضي الله عنها- بنت خويلد على سائر أمهات المسلمين؟","title":"فضائل خديجة رضي الله عنها","answer":"الجواب: ذكر العلماء في فضائلها أنها أول زوجة تزوجها النبي ﷺ وأنها أم أكثر أولاده -رضي الله عنها- وهي أنه كان يحبها كثيرًا -عليه الصلاة والسلام- ويذبح الشاة في بعض الأحيان، ويتصدق بها على صواحباتها، حتى قال بعض أهل العلم: إنها أفضل النساء. والصواب: أن أفضل النساء عائشة، وخديجة أيضًا من أفضل النساء، والنساء الفضليات اللاتي هن أفضل النساء خمس: خديجة، وعائشة، وفاطمة، وآسية امرأة فرعون، ومريم بنت عمران، هؤلاء خمس هم أفضل النساء، وأفضلهن عائشة؛ لقوله ﷺ: فضل عائشة على النساء كفضل الثريد على سائر الطعام نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12147/فضاىل-خديجة-رضي-الله-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53603.mp3","categories":["التاريخ والسيرة"]},{"id":13893,"question":"هذا السائل إبراهيم أبو حامد من الرياض له مجموعة من الأسئلة، يقول: ما هي مناسبة قول الرسول ﷺ: صبرًا آل ياسر فإن موعدكم الجنة؟","title":"ما مناسبة حديث (صبرًا آل ياسر فإن موعدكم الجنة)؟","answer":"الجواب: هذا قال لهم ﷺ لما كانوا يعذبون، كان ياسر وعمار وأم عمار يعذبون، فيقول لهم: صبرًا يا آل ياسر فإن موعدكم الجنة لأن كفار قريش كانوا يعذبون المسلمين في مكة، ومن ذلك: آل ياسر وبلال وغيرهم، فالرسول ﷺ صبرهم وشجعهم على الصبر، وأن لهم في هذا الخير العظيم، وأن الله جل وعلا سوف يدخلهم الجنة على صبرهم على دين الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12258/ما-مناسبة-حديث-صبرا-ال-ياسر-فان-موعدكم-الجنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53804.mp3","categories":["التاريخ والسيرة","شروح الحديث"]},{"id":13938,"question":"أفيدوني لو تكرمتم عن كتاب البداية والنهاية، ثم رشحوا لي بعضًا من الكتب لتكون نواة لمكتبتي؟ جزاكم الله خيرًا.","title":"التعريف بكتاب البداية والنهاية وكتب يُنصح باقتنائها","answer":"الجواب: البداية والنهاية كتاب عظيم للحافظ ابن كثير رحمه الله، وتاريخ عظيم إسلامي ذكر فيه أخبار الأنبياء الماضين، ثم ذكر فيه خبر نبينا ﷺ وسيرته، ثم ذكر مغازيه عليه الصلاة والسلام، ثم ذكر ما بعده إلى القرن الثامن إلى نصف القرن الثامن، فينبغي اقتناءه والاستفادة منه، فهو كتاب عظيم ذكر فيه الأحاديث والآثار وكلام أهل العلم في التاريخ وهو كتاب جيد. وننصحك باقتناء الكتب المفيدة مثل: المغني لـموفق الدين ابن قدامة، مثل: شرح المهذب للنووي، مثل: مجموع الرسائل لشيخ الإسلام ابن تيمية، مثل: مجموعة رسائل أئمة الدعوة، مثل: فتح المجيد، مثل: تيسير العزيز الحميد شرح كتاب التوحيد، كتاب التوحيد، كتب الشيخ محمد رحمه الله، كتاب مختصر السيرة النبوية، والسيرة أيضًا لابنه عبد الله، كلها كتب جيدة، بلوغ المرام تحفظ ما تيسر منه، عمدة الحديث، منتقى الأخبار، نيل الأوطار شرح المنتقى، تفسير الشوكاني، تفسير البغوي، تفسير ابن كثير كلها كتب مفيدة جيدة. نعم.\nالمقدم: طيب جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12339/التعريف-بكتاب-البداية-والنهاية-وكتب-ينصح-باقتناىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48211.mp3","categories":["العالم والمتعلم","التاريخ والسيرة"]},{"id":14364,"question":"السائلة (أ. ت) تقول: قرأت بأن النبي ﷺ مات عن فدك -كتبت هكذا- عن فدك وأموال، وكذلك قرأت بأن النبي ﷺ مات ولم يترك دينارًا ولا درهمًا كيف أوفق بين هذين؟","title":"الجمع بين «ما ترك النبي دينارًا..» وتركه أرض خيبر وفدك","answer":"الجواب: نعم، توفي وما خلف نقودًا، ما جاءه من النقود أنفقها -عليه الصلاة والسلام-، لكن خلف أراضٍ في خيبر وفي فدك أراضٍ للمسلمين؛ لمصلحة المسلمين، الرسل والأنبياء ما يورثون دينارًا ولا درهمًا، إنما يورثون ما ينفع المسلمين، ما تركوه فهو صدقة، تصرف في مصالح المسلمين، كما قال ﷺ: نحن معاشر الأنبياء لا نورث، ما تركناه فهو صدقة هو ما ورث دراهم ولا دنانير، وإنما خلف أرضًا في خيبر وفدك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12844/الجمع-بين-ما-ترك-النبي-دينارا-وتركه-ارض-خيبر-وفدك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55106.mp3","categories":["شروح الحديث","التاريخ والسيرة"]},{"id":15914,"question":"أخيرًا: يسأل سماحتكم فيقول: أرجو إعطاءنا فكرة عن الإسراء والمعراج بالرسول ﷺ.","title":"ما حقيقة الإسراء والمعراج وكيفيته؟","answer":"الجواب: الرسول ﷺ بعدما مضى عليه عشر سنين في مكة، يدعو الناس إلى توحيد الله، وترك الشرك، أسري به إلى بيت المقدس، ثم عرج به إلى السماء، وجاوز السبع الطباق، وارتفع فوق السماء السابعة -عليه الصلاة والسلام-، معه جبرائيل، فأوحى الله إليه ما أوحى، وفرض عليه الصلوات الخمس، الظهر، والعصر، والمغرب، والعشاء، والفجر، فرضها الله خمسين، فلم يزل النبي ﷺ يسأل ربه التخفيف؛ حتى جعلها خمسًا سبحانه، فضلاً منه ، ونادى منادٍ: إني قد أمضيت فريضتي، وخففت عن عبادي. فنزل بها -عليه الصلاة والسلام- في ليلة الإسراء، وأنزل الله في هذا قوله سبحانه: سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الأَقْصَى الَّذِي بَارَكْنَا حَوْلَهُ [الإسراء:1] فهذه الآية العظيمة بين فيها سبحانه الإسراء، أسري به من مكة على البراق، وهو دابة فوق الحمار ودون البغل، خطوه عند منتهى طرفه، كما أخبر به النبي ﷺ، فركبه هو وجبرائيل حتى وصل إلى بيت المقدس، وصلى هناك بالأنبياء. ثم عرج به إلى السماء، واستأذن له جبرائيل عند كل سماء، فيؤذن له، ووجد في السماء الدنيا آدم ، آدم أباه -عليه الصلاة والسلام-، فرحب به وقال: مرحبًا بالنبي الصالح، والابن الصالح، ثم لما أتى السماء الثانية وجد فيها عيسى ويحيى، ابني الخالة، فرحبا به، وقالا: مرحبًا بالنبي الصالح، والأخ الصالح، ثم عرج به إلى السماء الثالثة فوجد فيها يوسف -عليه الصلاة والسلام-، فرحب به، وقال: مرحبًا بالنبي الصالح، والأخ الصالح، ثم عرج به إلى السماء الرابعة فوجد فيها إدريس، فرحب به، وقال: مرحبًا بالنبي الصالح، والأخ الصالح، ثم عرج به إلى السماء الخامسة فوجد فيها هارون -عليه الصلاة والسلام-، فرحب به، قال: مرحبًا بالنبي الصالح، والأخ الصالح، ثم عرج به إلى السادسة فوجد فيها موسى -عليه الصلاة والسلام-، فرحب به، وقال: مرحبًا بالنبي الصالح، والأخ الصالح، ثم عرج به إلى السماء السابعة، فوجد فيها إبراهيم أباه -عليه الصلاة والسلام- هو من ذرية إبراهيم، محمد من ذرية إبراهيم -عليه الصلاة والسلام- فرحب به إبراهيم، وقال: مرحبًا بالنبي الصالح، والابن الصالح، مثلما قال آدم، مرحبًا بالنبي الصالح، والابن الصالح. ثم عرج به إلى مستوى رفيع، فوق السماء السابعة، سمع فيهن من صريف الأقلام، التي يكتب بها القضاء والقدر، فكلمه الله ، وفرض عليه الصلوات الخمس خمسين، ثم لم يزل يسأل ربه التخفيف، حتى جعلها سبحانه خمسًا، فضلًا منه وإحسانًا، فهي خمس في الفرض، وفي الأجر خمسون، والحمد لله، فضلًا من الله ، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14508/ما-حقيقة-الاسراء-والمعراج-وكيفيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_708/nour_70805.mp3","categories":["التاريخ والسيرة"]},{"id":15918,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية دمشق، باعثها مستمع من هناك رمز إلى اسمه بالحروف (ع. ع) أخونا يسأل ثلاثة أسئلة، في أحدها يقول: أريد نبذة عن الدعوة السلفية، وشيخ الإسلام محمد بن عبدالوهاب. جزاكم الله خيرًا.","title":"نبذة عن الدعوة السلفية وحياة الشيخ محمد بن عبدالوهاب","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإن الدعوة السلفية هي الدعوة إلى ما بعث الله به نبيه محمد -عليه الصلاة والسلام-، هي الدعوة إلى التمسك بالقرآن العظيم، والسنة المطهرة، هذه الدعوة السلفية الدعوة إلى السير على المنهج الذي درج عليه الرسول ﷺ في مكة، ثم المدينة، من إبلاغ الدعوة إلى المسلمين وغيرهم، توجيه الناس إلى الخير، تعليمهم ما بعث الله به نبيه من توحيد الله، والإخلاص له، والإيمان برسوله محمد ﷺ، وترك الإشراك بالله ، والقيام بما أمر الله به ورسوله، وترك ما نهى الله عنه ورسوله، هذه هي الدعوة السلفية، وعليها درج أصحاب النبي ﷺ، فأصحاب النبي ﷺ بعد وفاته ساروا على نهجه في الدعوة إلى توحيد الله، وإنكار الشرك، وتوجيه الناس إلى توحيد الله في أقوالهم وأعمالهم، كما أمرهم الله بذلك في قوله : يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21] وفي قوله سبحانه: وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا [النساء:36] وفي قوله سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلاةَ وَيُؤْتُوا الزَّكَاةَ وَذَلِكَ دِينُ الْقَيِّمَةِ [البينة:5].\nفالرسول ﷺ دعا إلى هذا، وكان المشركون يتعلقون بالقبور بالأموات بالأصنام والأشجار والأحجار: يدعونها، يتمسحون بها، يتبركون بها، يستشفعون بها، يذبحون لها، ينذرون لها؛ فنهاهم عن ذلك -عليه الصلاة والسلام-، وأخبرهم أنها لا تنفع ولا تضر، وأن الواجب إخلاص العبادة لله وحده، وقال: يا قومي قولوا: لا إله إلا الله تفلحوا. فلما فتح الله عليه مكة بعد الهجرة؛ كسر الأصنام، وهدم العزى، وكانت شجرة تعبد، وهدم مناة وكانت صخرة تعبد، وهدم اللات وكانت تعبد في الطائف، وهكذا جميع الأصنام كسرها، وبعث إلى القبائل والرؤساء يدعوهم إلى توحيد الله، ويأمرهم بترك عبادة الأصنام والأوثان والأولياء والأنبياء والملائكة، العبادة حق الله وحده؛ لأن الله سبحانه يقول: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] ويقول سبحانه: وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَسُولًا أَنِِ اُعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ [النحل:36] ومعنى أَنِ اُعْبُدُوا اللَّهَ وحدوا الله يعني: خصوه بالعبادة هو الذي يدعى، يرجى، يسأل، يسجد له، يركع له، يذبح له، ينذر له، أما القبور فلا يتعلق بها، لا يبنى عليها لا مساجد ولا غيرها، ولا يدعى لها من دون الله، ولا يستغاث بهم، ولا يطلب منهم الشفاعة؛ الشفاعة لله وحده قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا [الزمر:44].\nوقد أنكر الله على المشركين في قوله سبحانه: وَيَعْبُدُونَ مِنْ دُونِ اللَّهِ مَا لا يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَيَقُولُونَ هَؤُلاءِ شُفَعَاؤُنَا عِنْدَ اللَّهِ[يونس:18] فأنكر الله عليهم بقوله: قُلْ أَتُنَبِّئُونَ اللَّهَ بِمَا لا يَعْلَمُ فِي السَّمَوَاتِ وَلا فِي الأَرْضِ سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ[يونس:18] وقال سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ ۝ أَلا لِلَّهِ الدِّينُ الْخَالِصُ [الزمر:2-3] ثم قال سبحانه: وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى[الزمر:3] يعني: يزعمون أنهم عبدوهم للتقريب، يقولون: مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَى [الزمر:3] يعني: ما عبدنا اللات والعزى والأنبياء والملائكة ودعوناهم واستغثنا بهم؛ إلا ليقربونا إلى الله زلفى.\nفأنكر الله عليهم ذلك، وأكذبهم، فقال سبحانه: إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ فِي مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ اللَّهَ لا يَهْدِي مَنْ هُوَ كَاذِبٌ كَفَّارٌ [الزمر:3] بين سبحانه أنهم كذبة في قولهم: إنها تقربهم إلى الله زلفى، كفرة في عبادتهم الأصنام والملائكة والأنبياء. فلا يجوز أن يؤتى صاحب القبر، ويقول: يا سيدي فلان انصرني، أو أغثني، أو اقض حاجتي، أو اشفع لي، أو أنا في جوارك، كل هذا منكر كل هذا من الشرك الأكبر. في حياته لا بأس إذا كان حي تقول: يا فلان اشفع لي، مثل ما كان الصحابة في حياة النبي ﷺ يقول: اشفع لنا يارسول الله، ادع الله لنا، كان يستغيث لهم إذا أجدبوا في خطبة الجمعة وفي غيرها، وكان يدعو لهم، لا بأس في حياته.  وهكذا يوم القيامة، إذا بعثه الله يشفع للناس يوم القيامة، أما بعد موته في البرزخ فلا يدعى لا هو ولا غيره، لا الأنبياء ولا الملائكة ولا الصالحون، لا يدعون مع الله، ولا يستغاث بهم، لكن تقول: يا رب اغفر لي، يا رب ارحمني، يا رب أصلح قلبي، يا رب ارزقني، يا رب فرج كربتي، يا رب أصلح أولادي، يا رب انصرني على عدوي، يا رب شفع في نبيك، يا رب اجعلني من أهل شفاعة نبيك -عليه الصلاة والسلام-، يا رب وفقني لطاعتك واتباع شريعتك، هكذا تقول تسأل ربك. هذا هو الطريق الصحيح، هي هذه الطريقة السلفية التي درج عليها الرسول ﷺ، ودرج عليها أصحابه، ثم التابعون بعدهم بإحسان درجوا على هذا، وكان الصحابة ومن بعدهم يدعون إلى هذا الطريق: التمسك بكتاب الله، وسنة رسوله ﷺ، وإلى إخلاص العبادة لله وحده، لا يدعى معه ملك مقرب، ولا نبي مرسل، ولا صاحب قبر، ولا جني ولا شجر ولا صنم، ولا غير ذلك، العبادة حقًا الله وحده يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21]، وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]، وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينََ حُنَفَاءَ [البينة:5] مع الإيمان بأن الرسول ﷺ هو خاتم الأنبياء، لا نبي بعده، أرسله الله إلى الناس كافة الجن والإنس، لا بد من هذا الإيمان أن تؤمن بأن محمد بن عبد الله بن عبد المطلب الهاشمي العربي المكي، ثم المدني، هو رسول الله حق -عليه الصلاة والسلام-، وهو أفضل الخلق، هو سيد ولد آدم، تؤمن بهذا، وتؤمن بأن الله أرسله إلى الناس عامة: الجن والإنس، من أجاب دعوته، واتبع ما جاء به؛ فله الجنة، ومن حاد عن سبيله فله النار.\nهو خاتم الأنبياء ليس بعده نبي، من ادعى النبوة بعده كـالقاديانية يكون كافرًا؛ لأن الله سبحانه يقول: مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ [الأحزاب:40] -عليه الصلاة والسلام-، وقد تواترت الأحاديث عن رسول الله ﷺ أنه خاتم الأنبياء، يقول: إني خاتم الأنبياء لا نبي بعدي -عليه الصلاة والسلام-. ثم من تمام الدعوة السلفية: طاعة الله ورسوله، فعل الأوامر، وترك النواهي: الصلاة تصلي كما شرع الله، تزكي كما شرع الله، تصوم كما شرع الله، تحج كما شرع الله، تبر والديك، تصل أرحامك، تدعو إلى الله بالحلم والهدى، تأمر بالمعروف، تنهى عن المنكر بالأسلوب الحسن، بالرفق والحكمة، تدع المعاصي: كالزنا والعقوق والربا، قطيعة الرحم، شرب المسكر إلى غير هذا من المعاصي، تدعها، تحذرها؛ طاعة لله، وتعظيمًا لله، واتباعًا لشريعته، ترجو ثوابه، وتخشى عقابه، كل هذا داخل في الدعوة السلفية. أما الشيخ محمد بن عبد الوهاب -رحمه الله- فهو إمام عالم، دعا إلى الله  دعا إلى هذه الطريقة، كان -رحمة الله عليه- في نجد.......، من بلاد نجد، ثم انتقل إلى العينية كذلك، وهي بلدة معروفة قرب الدرعية، فتعلم العلم، وتفقه في الدين، ثم سافر إلى الحرمين، وتعلم في مكة والمدينة، ثم شرح الله صدره للدعوة السلفية، كان أهل نجد يتعلق بعضهم بالأوثان بالقبور، بالأشجار والأحجار، كما هو واقع في بلدان كثيرة، فشرح الله صدره لحقيقة التوحيد، وللدعوة السلفية التي درج عليها الرسول ﷺ وأصحابه، فلما انشرح صدره لهذا الأمر، وعرف أدلته؛ دعا إلى هذا، دعا قومه ودعا الناس في نجد إلى توحيد الله. وكان في نجد قبر لـزيد بن الخطاب أخي عمر  في الجبيلة قرب الدرعية يدعى ويعبد من دون الله، كانت هناك أشجار وأحجار تعبد من دون الله، فنهى عن هذا، ونهى عن التعلق بالأموات والقبور والأشجار والأحجار، وأخبرهم أن هذا شرك بالله، وأن الله بعث نبيه ﷺ يدعو إلى توحيد الله، وينكر هذا الشرك، وأن الصحابة كذلك فدعا إلى الله في نجد في الدرعية أولًا في حريملاء، ثم في العينية، ثم انتقل إلى الدرعية، وساعده محمد بن سعود أمير الدرعية على ذلك، واستمر في الدعوة إلى توحيد الله، والإخلاص له، واتباع النبي ﷺ، وهدم القباب التي على القبور، وقطع الأشجار التي تعبد من دون الله، وهدم القبة التي على قبر زيد بن الخطاب إلى غير هذا من آثار الشرك، فأعانه الله على ذلك، وأعانه الأمير محمد بن سعود، ثم آل سعود بعده -جزاهم الله خيرًا-، ولم يزالوا عونًا للتوحيد إلى يومنا هذا، يدعون إلى الله، ويساعدون أهل العلم في الدعوة إلى توحيد الله، وإنكار الشرك، وإقامة الدين. هذه دعوة الشيخ محمد بن عبد الوهاب -رحمة الله عليه-، إمام عالم سلفي العقيدة، يدعو إلى توحيد الله، وإلى اتباع شريعته، وينهى عن الشرك والبدع والخرافات والمعاصي، مثل ما كان الصحابة يدعون إلى الله، ومثل ما كان الشافعي وأحمد بن حنبل ومالك وغيرهم من أئمة الإسلام يدعون إلى توحيد الله، والإخلاص له، ومثل ما كان شيخ الإسلام ابن تيمية في زمانه في القرن السابع والثامن، و ابن القيم -رحمه الله- في القرن الثامن، وابن كثير وأشباههم يدعون إلى الله، هو على طريقهم -رحمه الله-. فهو سلفي إمام يدعو إلى توحيد الله، وطاعة الله، واتباع شريعته.  وأما أعداؤه من القبوريين الذين يرمونه بأنه مبتدع، أو أنه يبغض الأولياء، كل هذا باطل، يكذبون عليه مثل ما كذبوا على النبي ﷺ وعلى غيره، فهو يدعو إلى توحيد الله، ويدعو إلى اتباع النبي ﷺ، ويدعو إلى الحق والهدى، ويدعو إلى الإخلاص لله، وترك البدع والخرافات التي بلي بها كثير من الناس، فهو إمام مهتد موفق يدعو إلى توحيد الله وطاعته، ويدعو إلى العقيدة السلفية، وهكذا أنصاره من آل سعود، ومن العلماء والأخيار، كلهم دعاة إلى الحق. وأما تسمية الوهابية، فهذا لقبهم به أعداؤهم؛ للتنفير فهم محمدية، هو محمد، ما هو عبد الوهاب هو، هو محمد بن عبد الوهاب، أبوه اسمه عبد الوهاب، الصواب يقال: محمدية؛ لأنه محمد، والنبي محمد -عليه الصلاة والسلام-، فهو من أتباع محمد -عليه الصلاة والسلام-، لكن أعداؤه من الجهال، أو الذين قلدوا الجهال، أو قلدوا الأعداء سموهم بالوهابية؛ جهلًا أو عنادًا وتنفيرًا من الحق، فلا ينبغي لعاقل أن يغتر بهذا اللقب الذي يغريهم به الأعداء، ويقولون: إنهم أعداء للدين، أو أنهم أعداء للحق، أو أنهم أهل بدعة كل هذا باطل. الوهابية: دعاة للحق، دعاة للسلفية، دعاة إلى ما كان عليه الرسول ﷺ وما كان عليه الصحابة، ومن بعدهم من أئمة الإسلام، فالشيخ محمد بن عبد الوهاب وذريته وأتباعه إلى يومنا هذا يدعون إلى توحيد الله، وإلى اتباع شريعته، وينهون عن الشرك بالله، وعن البدع التي ما أنزل الله بها من سلطان، ومن البدع: البناء على القبور، واتخاذ المساجد عليها؛ لأنها وسيلة للشرك، وإقامة الموالد والاحتفالات بالموالد؛ لأنها وسيلة للشرك، لم يفعلها النبي ﷺ ولا أصحابه، والخير كله في اتباعهم؛ لأن الله يقول -جل وعلا-: وَالسَّابِقُونَ الأَوَّلُونَ مِنَ الْمُهَاجِرِينَ وَالأَنصَارِ وَالَّذِينَ اتَّبَعُوهُمْ بِإِحْسَانٍ رَضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ [التوبة:100] الآية، فأتباعهم بإحسان هم الذين ساروا على نهجهم، لم يزيدوا على ذلك، ولم ينقصوا، بل ساروا على نهجهم في توحيد الله، والإخلاص له، واتباع الشريعة وتعظيمها، وترك ما نهى الله عنه من البدع، وترك المعاصي، والدعوة إلى توحيد الله، وإلى اتباع رسوله ﷺ قولًا وعملًا، هذه طريقة السلف الصالح من الصحابة والتابعين لهم بإحسان، وهذه طريقة الشيخ محمد بن عبد الوهاب، وطريقة أتباعه من آل سعود وغيرهم من العلماء الذين ساروا على نهجه.\nوهكذا أتباعهم من العلماء الذين ساروا على نهجه في الهند وفي الشام وفي العراق وفي مصر وفي كل مكان، له أتباع كثيرون في أقطار كثيرة، وفي مناطق كثيرة من العالم، عرفوا الحقيقة، عرفوا دعوته الطيبة من كتبه، ومن كتب أتباعه، وأنها دعوة سلفية، دعوة إلى توحيد الله، واتباع شريعته، واتباع نبيه محمد -عليه الصلاة والسلام-. فنصيحتي لكل مسلم أن يتقي الله، وأن يعرف الحق بدليله، لا بالتقليد، وقول الجهال، واتباع الجهال، ولكن بالدليل، ينظر كتب القوم ينظر ما قرروه في الدرر السنية من كتبهم فتح المجيد، كتاب التوحيد، تيسير العزيز الحميد، إلى غير هذا من كتبهم وردودهم؛ حتى يعرف الحقيقة، يعلم أنهم على الحق والهدى، وأنهم دعاة إلى توحيد الله، وإلى اتباع شريعته، وإلى ترك ما نهى الله عنه ورسوله. هذه دعوة الوهابية هذا طريق الشيخ محمد بن عبد الوهاب -رحمه الله- وهذه طريقة أتباعه وأنصاره من علماء نجد وغيرهم من آل سعود وغيرهم.  نسأل الله أن يثبت الجميع على الهدى، وأن يصلح قلوب الجميع، وعمل الجميع، وأن يهدي الضال حتى يستقيم على الحق، نسأل الله أن يهدي الضالين، وأن يعلم الجاهلين، حتى يعرفوا الحق بدليله، ونسأل الله أن يهدي المتعصبين، وأصحاب الهوى حتى يدعوا التعصب والهوى، وحتى ينقادوا للحق، ويتبعوا ما جاء به الرسول ﷺ وينقادوا له بالدليل لا بتقليد الجهلة، وتقليد أصحاب الهوى، فالتقليد لأصحاب الهوى والتقليد للجهلة يضر ولا ينفع. فالواجب على طالب العلم أن يأخذ الحق بالدليل، وينظر في كتب القوم الذين يسمع عنهم أشياء تخالف الشرع، ينظر كتبهم حتى يعرف الحقيقة بأدلتها، وحتى يتكلم عن علم وعن بصيرة، لا عن تقليد زيد وعمرو، ونحو ذلك. نسأل الله للجميع التوفيق والهداية، ونسأل الله أن يصلح أحوال المسلمين جميعًا في كل مكان، نسأل الله أن يمنحهم الفقه في الدين، وأن يهدينا وإياهم صراطه المستقيم، وأن يمن على جميع المسلمين بالفقه في دين الله والتمسك بكتاب الله، وسنة رسوله محمد -عليه الصلاة والسلام-، والوقوف عند حدودهما؛ إنه  جواد كريم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14512/نبذة-عن-الدعوة-السلفية-وحياة-الشيخ-محمد-بن-عبدالوهاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_709/nour_70901.mp3","categories":["التاريخ والسيرة"]},{"id":16273,"question":"المستمع مجدي عبد الغني السيد من جمهورية مصر العربية يسأل ويقول: هل (يس) اسم من أسماء الرسول ﷺ أرجو إفادتي، وإفادتي عن بقية أسمائه، عليه أفضل الصلاة وأتم التسليم؟","title":"ما أسماء النبي ﷺ؟ وهل (يس) و(طه) منها؟","answer":"الجواب: (يس) ليست من أسمائه ﷺ على الصحيح، وهكذا (طه) ليست من أسمائه، بعض الناس يظن ذلك، وليست من أسمائه لا (طه) ولا (يس) ولا غيرها من فواتح السور -عليه الصلاة والسلام- وإنما هي حروف مقطعة مثل: (الم) ومثل: (حم) ومثل: (المص) وأشباهها، كلها حروف مقطعة في أوائل السور، لله فيها الحكمة العظيمة -سبحانه وتعالى- وليست أسماء للنبي ﷺ ولكن يقال: سورة طه، سورة يس، سورة المص، سور حم كذا لا بأس. وأما أسماؤه فهي كثيرة -عليه الصلاة والسلام- لكن أشهرها محمد، وأحمد -عليه الصلاة والسلام- والماحي، والحاشر، والمقفي، كما جاء في الأحاديث، نبي التوبة، نبي الرحمة، نبي الملحمة، كل هذه من أسمائه -عليه الصلاة والسلام- وأشهرها محمد، وأحمد -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/14968/ما-اسماء-النبي-ﷺ-وهل-يس-وطه-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80903.mp3","categories":["التاريخ والسيرة"]},{"id":16287,"question":"المستمع مجدي عبد الغني السيد من جمهورية مصر العربية يسأل ويقول: هل (يس) اسم من أسماء الرسول ﷺ أرجو إفادتي، وإفادتي عن بقية أسمائه، عليه أفضل الصلاة وأتم التسليم؟","title":"ما أسماء النبي ﷺ؟ وهل (يس) و(طه) منها؟","answer":"الجواب: (يس) ليست من أسمائه ﷺ على الصحيح، وهكذا (طه) ليست من أسمائه، بعض الناس يظن ذلك، وليست من أسمائه لا (طه) ولا (يس) ولا غيرها من فواتح السور -عليه الصلاة والسلام- وإنما هي حروف مقطعة مثل: (الم) ومثل: (حم) ومثل: (المص) وأشباهها، كلها حروف مقطعة في أوائل السور، لله فيها الحكمة العظيمة -سبحانه وتعالى- وليست أسماء للنبي ﷺ ولكن يقال: سورة طه، سورة يس، سورة المص، سور حم كذا لا بأس. وأما أسماؤه فهي كثيرة -عليه الصلاة والسلام- لكن أشهرها محمد، وأحمد -عليه الصلاة والسلام- والماحي، والحاشر، والمقفي، كما جاء في الأحاديث، نبي التوبة، نبي الرحمة، نبي الملحمة، كل هذه من أسمائه -عليه الصلاة والسلام- وأشهرها محمد، وأحمد -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/14968/ما-اسماء-النبي-ﷺ-وهل-يس-وطه-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80903.mp3","categories":["التاريخ والسيرة"]},{"id":16704,"question":"تقول السائلة من الإمارات: السيدة عائشة أم المؤمنين -رضي الله عنها- تنادى بأم عبدالرحمن، فهل أنجبت للرسول ﷺ ابنًا؟ أم أن ذلك اسم ناداها به الرسول ﷺ؟","title":"لماذا تكنى عائشة رضي الله عنها بأم عبدالله؟","answer":"الجواب: لا، تنادى بأم عبدالله، مو[1] بأم عبدالرحمن، تنادى بأم عبدالله، تسمى أم عبدالله، نعم، ولم تلد للنبي ﷺ ولكن شيء لقبت به، أم عبدالله -رضي الله عنها- نعم. المقدم: رضي الله عنها وأرضاها.","link":"https://binbaz.org.sa/fatwas/15438/لماذا-تكنى-عاىشة-رضي-الله-عنها-بام-عبدالله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58420.mp3","categories":["التاريخ والسيرة"]},{"id":16943,"question":"السائلة زكية وهدى من المستمعات لهذا البرنامج، لهن هذا السؤال، ومجموعة من الأسئلة، يقلن في هذا السؤال سماحة الشيخ: سمعنا في أحد الأشرطة الدينية بأنه عندما مات الخليفة عمر بن عبدالعزيز -رحمه الله- طارت صحيفة من السماء كتب عليها \"براءة عمر بن عبدالعزيز من النار\" فهل هذا صحيح؟","title":"ما صحة نزول صحيفة فيها براءة عمر بن عبدالعزيز؟","answer":"الجواب: ما بلغني هذا، لم يبلغني هذا. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15727/ما-صحة-نزول-صحيفة-فيها-براءة-عمر-بن-عبدالعزيز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58616.mp3","categories":["التاريخ والسيرة"]},{"id":17780,"question":"يقول السائل من أسئلته: من هو أول الأنبياء: إدريس أم نوح عليهما السلام؟","title":"من أول الأنبياء؟","answer":"الجواب: أول الأنبياء بعد ما وقع الشرك نوح بعدما وقع في الأمة، وأما قبل ذلك فهو آدم هو أول الرسل وأول الأنبياء، آدم أبونا عليه الصلاة والسلام، فهو أول رسول وأول نبي، وكانت ذريته على الإسلام عشرة قرون، ثم وقع الشرك في قوم نوح، فأرسل الله إليهم نوحًا، فصار نوح أول الرسل بعد وقوع الشرك. نعم.\nالمقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16763/من-اول-الانبياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59630.mp3","categories":["التاريخ والسيرة"]},{"id":17957,"question":"هل تزوج عثمان بن عفان  من ابنتي الرسول ﷺ بنفس الوقت، وهل هذا جائز؟","title":"زواج عثمان بن عفان ببنتي رسول الله ﷺ","answer":"الجواب: إيه، نعم، تزوج رقية وأم كلثوم، وكلتاهما ماتتا في حسابه، تزوج أم كلثوم بعد رقية، ماتت رقية يوم بدر، ثم تزوج أم كلثوم ثم ماتت، كلتاهما ماتتا في عهد النبي ﷺ وهما زوجتا عثمان . وزينب أخذها أبو العاص بن الربيع، وفاطمة عند علي، أربع، أربع رضي الله عنهن كلهن متن في حياة النبي ﷺ إلا فاطمة ماتت بعده بستة أشهر رضي الله عنها.\nالمقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/17005/زواج-عثمان-بن-عفان-ببنتي-رسول-الله-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78020.mp3","categories":["التاريخ والسيرة"]},{"id":18143,"question":"شيخ عبد العزيز بعد وجود الإعلام الخميني بدأ الناس يسألون هذا النوع من الأسئلة، فمثلًا هذا  بعض الناس يظن أن هذا الكلام وهو: ما فضلكم -يبدو- أبو بكر بصلاة ولا صيام ولكن هو سر وقر في قلبه.يظنون أن هذا الكلام هو حديث، ويكتبونه في كتبهم على أنه حديث صحيح، أرجو أن توضحوا هذا للناس، وأرجو أن تذكروا لي الأحاديث التي جاء فيها وصف الرسول ﷺ؛ لأني لا أملك الكتب التي يوجد فيها مثل هذه الأشياء.","title":"بيان فضل أبي بكر رضي الله عنه والتحذير من الرافضة","answer":"الجواب: هذا ليس من كلام النبي ﷺ وليس من كلام الصحابة إنما هو من كلام بعض السلف، \"ما فضلكم أبو بكر بكثير صوم ولا صلاة ولكنه شيء وقر في قلبه\"، هذا من كلام بعض السلف، والصديق  هو أعلم الصحابة وأفضلهم وأكملهم إيمانًا، فقد أعطاه الله من العلم والفضل والتقوى والخير ما لم يعط غيره، ومن تأمل سيرته وتأمل أعماله وفتاواه عرف ما عنده من العلم والفضل وقوة الإيمان وكماله، فهو أفضل الصحابة وخيرهم وهو إمامهم  وأرضاه بإجماع المسلمين. وقد تواتر النقل عن أمير المؤمنين علي بن أبي طالب  أنه قال على المنبر لما سأله ابنه محمد بن علي قال: «يا أبتاه! من خير هذه الأمة؟ قال: أبو بكر ، قال: ثم من؟ قال: عمر » هكذا تواتر عن علي  الذي الرافضة الآن تسب أبا بكر وتسب عمر وترى أن خلافتهما غير صحيحة، هذا علي  يشهد على رءوس الأشهاد أن الصديق هو أفضل الأمة وأن بعده عمر  هذا إجماع الأمة، ولكن الرافضة ومن سار في ركابهم خالفوا الإجماع وخالفوا النصوص واتبعوا أهواءهم نسأل الله العافية. نعم. المقدم: الخمينيون سماحة الشيخ من الرافضة ؟ الشيخ: نعم، الخميني من رءوس الرافضة . المقدم: من رءوسهم؟ الشيخ: نعم، هم وأتباعهم رافضة، وهم الذين يغلون في الأئمة الاثنا عشر، يغلون فيهم ويعظمونهم ويعتقدون فيهم أنهم يعلمون الغيب وأنهم معصومون، ويدعونهم من دون الله ويستغيثون بهم وينذرون لهم، هذا موجود في كتبهم، من راجع الكافي وغير الكافي وجد ذلك، نسأل الله السلامة، نعم، نسأل الله أن يردهم للتوبة. نسأل الله أن يردهم للتوبة ويكفي المسلمين شرهم وشر أمثالهم؛ لأنهم ادعوا الإسلام وهم يخالفون الإسلام، وهم يحاربون الإسلام في الحقيقة. نعم. المقدم: وقد اتضح هذا ولاشك. الشيخ: نسأل الله العافية. المقدم: كيف تنصحون المسلمين بأن يواجهوا هذا الفكر الذي بدأ يمتد في هذه الآونة شيخ عبد العزيز ؟ الشيخ: ننصح المسلمين أن لا يغتروا بدعواتهم فإن دعواتهم التي يقولونها وما يزعمونه من أنهم على الإسلام كله لا أصل له، ولا صحة له، كله من عمل النفاق، هم أهل النفاق وأهل التقية، ومن طالع كتبهم عرف ذلك، فالذي ينبغي للمؤمنين والمسلمين أن يعرفوا أن هذه الدعاوى ودعوى الجمهورية الإسلامية كله شيء لا حقيقة له، وإنما هو مظاهر إسلامية والباطن خلاف الإسلام، الباطن وثنية والعداء للإسلام والعداء لنبي الإسلام وللصحابة جميعًا، وعدم الترضي عنهم، بل كفروهم وفسقوهم إلا نفرًا قليلًا. فالمقصود أن الخميني وأتباعه هم من أعيان الرافضة ومن المعظمين لعقيدة الرافضة والمتمسكين بها والقائلين بها، وهم الذين يعظمون الأئمة الاثني عشر، ويزعمون أنهم هم الأئمة، وهم الذين يجب أن تكون لهم الولاية، وأن ولاية غيرهم باطلة، وعلى رأسهم علي  أما علي فقد صدقوا علي هو رجل صالح، وهو الرابع بعد الثلاثة، وهو أفضلهم بعد الثلاثة، أفضل الصحابة بعد الثلاثة، وهكذا الحسن والحسين من الصحابة رضي الله عنهم وأرضاهم ولكنهم لم يتولوا شيئًا إلا الحسن تولى قليلًا ثم عزل نفسه وجعل الإمامة والولاية لـمعاوية  وأما الحسين ومن بعده فلم يتولوا شيئًا ولكن الرافضة ليس عندهم بصيرة وليس عندهم إلا الدعاوى التي لا أساس لها. نعم. المقدم: نسأل الله لهم الهداية.","link":"https://binbaz.org.sa/fatwas/17185/بيان-فضل-ابي-بكر-رضي-الله-عنه-والتحذير-من-الرافضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90506.mp3","categories":["مسائل متفرقة في العقيدة","التاريخ والسيرة"]},{"id":18156,"question":"أرجو أن تذكروا لي عدة أحاديث عن وصف النبي ﷺ، ذلكم أني في غاية الشوق إلى معرفة المزيد عن أوصافه عليه الصلاة والسلام؟","title":"بعض صفات النبي ﷺ الخَلْقِية","answer":"الجواب: ثبت عنه ﷺ أنه كان وسطًا من الرجال، ليس بالقصير ولا بالطويل بل بين ذلك، وكان أبيض مشربًا بالحمرة عليه الصلاة والسلام، وكان كث اللحية عليه الصلاة والسلام، ضخم الكراديس، إذا مشى كأنما ينحدر من صبب، يعني: يمشي قويًا عليه الصلاة والسلام، وكان الغالب عليه أنه لا يلتفت عليه الصلاة والسلام إلا إذا دعت الحاجة إلى ذلك، فهذا كله من صفاته عليه الصلاة والسلام. نعم. المقدم: هل تنصحونه بكتب معينة تثقفه في ... ؟ الشيخ: نعم، ننصح لك بأن تقرأ السيرة سيرة الرسول ﷺ في البداية والنهاية لابن كثير المجلد السادس لابن كثير، دلائل النبوة للبيهقي رحمه الله، كذلك سيرة ابن هشام فيها بيان لكثير من صفاته عليه الصلاة والسلام. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17199/بعض-صفات-النبي-ﷺ-الخلقية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90510.mp3","categories":["التاريخ والسيرة"]},{"id":18630,"question":"يقول: النجاشي ملك الحبشة في عهد النبي ﷺ هل مات مسلمًا مؤمنًا برسول الله ﷺ أم مات على غير ذلك؟","title":"موت النجاشي أصحمة على الإسلام","answer":"الجواب: نعم، مات مسلمًا، \"أصحمة\" مات مسلمًا، وصلى عليه النبي ﷺ صلاة الغائب -عليه الصلاة والسلام- وكان رجلًا صالحًا، أكرم الصحابة وحماهم وصانهم، حتى رجعوا إلى مكة والمدينة، حتى رجع من رجع إلى مكة، ورجع من رجع إلى المدينة، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17745/موت-النجاشي-اصحمة-على-الاسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78713.mp3","categories":["التاريخ والسيرة"]},{"id":18857,"question":"هل تنصحونني بقراءة كتاب قصص الأنبياء لابن كثير؟","title":"تقييم كتاب قصص الأنبياء لابن كثير","answer":"الجواب: نعم، كتاب الحافظ ابن كثير كتاب جيد، وهو مأخوذ من كتابه البداية، فهي نسخة عظيمة ومفيدة، وهو من خير الكتب والمؤلف من خيرة العلماء، ومن حفاظهم -رحمه الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17992/تقييم-كتاب-قصص-الانبياء-لابن-كثير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92205.mp3","categories":["التاريخ والسيرة"]},{"id":19109,"question":"المستمع: عبد الله إبراهيم حسن زيد بعث برسالة يسأل فيها سؤالين في سؤاله الأول يسأل عن ذي القرنين وهل هو نبي؟وهل تتفضلون بإيراد شيء من قصته إذا أمكن؛ لأن هذا المستمع يطلب هذا في نهاية سؤاله؟جزاكم الله خيرًا.","title":"الاختلاف في نبوة ذي القرنين","answer":"الجواب: ذو القرنين ملك عظيم صاحب خير، وإحسان، وإصلاح، واختلف الناس في نبوته، والمشهور أنه ملك صالح، قصته معروفة في القرآن الكريم في كتاب الله ما يحتاج أن نقرأها، من أرادها وجدها في سورة الكهف، من أراد أن يقرأها فهي بحمد الله واضحة، وقصة بينة في كتاب الله ، وفيما بيَّنه سبحانه الكفاية عن هذا الرجل الكريم العظيم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18280/الاختلاف-في-نبوة-ذي-القرنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79706.mp3","categories":["التاريخ والسيرة"]}]
